W_EXTRA.push({"id":"PSJ","title":"박씨전","unit":"권","persons":{"박씨":{"name":"박씨","alias":["박부인","박씨 부인","정렬부인"],"sex":"F","note":"박처사의 딸, 이시백의 아내. 박색이었다가 허물을 벗음. 남장하지 않는 여성 영웅"},"박처사":{"name":"박처사","alias":["처사","선관"],"sex":"M","note":"금강산에 사는 신선. 박씨의 아버지이자 허물 벗는 술법을 가르친 이"},"이득춘":{"name":"이득춘","alias":["상공","대감","공"],"sex":"M","note":"일품 재상. 박씨를 알아보고 끝까지 감싸는 시아버지. 여든에 죽음"},"이시백":{"name":"이시백","alias":["시백","감사","병조판서","우의정","승상","우승상"],"sex":"M","note":"이득춘의 아들, 박씨의 남편. 박씨를 박대하다 뉘우침. 장원급제, 평안감사, 우의정"},"이득춘 부인":{"name":"이득춘 부인","alias":["부인","시어머니"],"sex":"F","note":"시백의 어머니. 박씨를 미워해 밥을 줄이게 함. 이득춘과 백 일 안에 죽음"},"계화":{"name":"계화","alias":["시비 계화","시녀 계화"],"sex":"F","note":"박씨의 시비. 노래를 부르고, 용울대를 베고 진언으로 우박을 부르는 박씨의 대리자"},"임금":{"name":"임금","alias":["전하","상"],"sex":"M","note":"조선 임금. 처음엔 선조로 시작하나 병자호란 대목에서 이름 없이 인조 대의 일을 겪음. 조복으로 박씨의 사정을 알아봄"},"남경 천자":{"name":"남경 천자","alias":["천자","황제"],"sex":"M","note":"명 황제. 임경업을 호국 구원병 대장으로 삼음"},"황재명":{"name":"황재명","alias":["원접사"],"sex":"M","note":"남경의 원접사. 임경업을 구원병 장수로 천거"},"임경업":{"name":"임경업","alias":["경업","임장군","부원수","의주부윤"],"sex":"M","note":"실존 명장. 호국을 구하고 의주를 지킴. 돌아가는 오랑캐를 치다가 왕명으로 길을 내줌"},"총마 가달":{"name":"총마 가달","alias":["가달"],"sex":"M","note":"호국을 침범한 세력. 임경업에게 패함"},"호왕":{"name":"호왕","alias":["호국 왕","오랑캐 왕"],"sex":"M","note":"북방 호국의 왕. 은혜를 저버리고 조선을 침략"},"호국 왕비":{"name":"호국 왕비","alias":["왕비"],"sex":"F","note":"천문·지리에 통한 호왕의 아내. 조선에 신인이 있음을 알고 자객과 우회 침공을 계획. 박씨의 거울상"},"길홍대":{"name":"길홍대","alias":["설중매"],"sex":"F","note":"호국 왕비가 보낸 여성 자객. 회양 관비 기생이라 속이고 들어왔다가 박씨에게 들킴"},"한우":{"name":"한우","alias":["적진 도원수"],"sex":"M","note":"호국 대장. 피화당의 진을 알아보고 용골대를 말림"},"용골대":{"name":"용골대","alias":["골대"],"sex":"M","note":"호국 대장. 동생의 원수를 갚으려다 피화당에서 패하고 박씨에게 빎"},"용울대":{"name":"용울대","alias":["울대"],"sex":"M","note":"용골대의 아우. 장안 약탈 중 피화당에 들어갔다가 계화에게 죽음"},"원두표":{"name":"원두표","alias":["좌의정"],"sex":"M","note":"박씨의 말을 따르자고 주장한 좌의정"},"김자점":{"name":"김자점","alias":[],"sex":"M","note":"박씨를 요망하다고 하며 임경업 소환을 막은 간신. 뒤에 오랑캐의 명으로 피화당을 공격"},"왕대비":{"name":"왕대비","alias":["왕비"],"sex":"F","note":"박씨의 요구로 호국에 끌려가지 않고 환궁"},"세자 삼 형제":{"name":"세자 삼 형제","alias":["세자","대군 삼 형제분"],"sex":"M","note":"호국에 볼모로 끌려감. 박씨는 십 년 뒤 모셔 올 사람이 있다고 예언"},"칙사":{"name":"칙사","alias":[],"sex":"M","note":"중국 사신. 박씨가 기른 천리마를 삼만 냥에 삼"},"말 장수":{"name":"말 장수","alias":[],"sex":"M","note":"종로에서 망아지를 판 사람. 지나친 값을 사양"},"노복들":{"name":"노복들","alias":["종들"],"sex":"M","note":"박씨를 박대하고 말값 이백 냥을 숨겼다가 들킴"},"재상가 부인들":{"name":"재상가 부인들","alias":["여러 부인"],"sex":"F","note":"꽃놀이에 박씨를 불러 오화단·명월단 등의 신이를 구경함"},"나무하는 아이들":{"name":"나무하는 아이들","alias":[],"sex":"M","note":"금강산에서 박처사가 사백 년 전 사람이라고 알려줌"}},"places":{},"paras":[{"c":1,"sub":"","t":"우리 동방 선조대왕(宣祖大王)께서 즉위하신 초기에 한양 성안에 한 재상이 있었는데, 성은 이씨요 이름은 득춘(得春)이었다. 어려서부터 학업에 힘써 열 살이 되기 전에 문필과 재덕이 나라 안에 이름났고, 사람을 알아보는 눈이 남달라 젊은 나이에 과거에 급제하였다. 벼슬이 일품에 올라 나라를 충성으로 섬기고 만인을 인의로 가르치니 위엄과 명망이 사방에 떨쳤다. 총명하고 영리하며 얼굴이 빼어나고 풍채가 늠름하여 두목지(杜牧之)에 견줄 만하니, 이 같은 인재는 우리 동방의 이름난 현인이었다. 게다가 술법에도 이름이 났고 남보다 갑절의 용맹을 지녔으니 참으로 한 시대의 영웅이었다. 일찍이 슬하에 아들 하나를 두었는데, 하나를 들으면 열을 알 만큼 지각이 뛰어나고 골격이 빼어나니 상공이 크게 사랑하여 이름을 시백(時白)이라 하였다.","sp":[[379,381,"P","이득춘"],[395,397,"P","이시백"]]},{"c":1,"sub":"","t":"이때 상공은 바둑 두기와 옥저 불기를 좋아하였는데 당할 사람이 없었다. 고요한 때에 밝은 달을 마주하여 옥저를 불면 그 가락이 끝이 없어 화단에 피었던 꽃이 저절로 떨어지니, 이런 재주는 실로 나라 안에서 으뜸이었다. 상공은 바둑과 옥저 부는 데 맞수를 얻지 못하여 근심하였는데, 하루는 어떤 사람이 해진 옷에 해진 갓을 쓰고 모양이 초라한 채로 사랑 앞에 와서 하룻밤 묵기를 청하였다. 자세히 보니 비록 옷차림은 남루하나 사람됨이 보통 사람과 달랐다. 상공의 밝은 눈으로 어찌 이런 도인을 몰라보겠는가. 또 속으로 생각하기를 '저 사람이 본래 천한 사람이라면 어찌 당돌하게 대청에 오르겠는가. 분명 보통 사람이 아니다.' 하고 말하였다. \"어떤 귀한 손님인지 모르겠으나 누추한 곳에 오셨습니까?\"","sp":[[3,5,"P","이득춘"],[122,124,"P","이득춘"],[254,256,"P","이득춘"]]},{"c":1,"sub":"","t":"하며 대청에 오르기를 청하시니, 그 사람이 대청에 올라 자리를 정한 뒤에 서로 성명을 통하였다. 그 사람이 말하였다. \"저는 집 없는 나그네로 이름난 산과 큰 절을 찾아다니며 사슴을 벗 삼아 세월을 보내었는데, 지금은 나이가 많아 강산을 두루 다니다가 그저 금강산에 머물며 죽기만 기다리고 있습니다. 성은 박이요 세상 사람들이 처사(處士)라고 부릅니다.\" 하거늘 상공이 그 말이 바르고 곧음을 듣고 과연 신선인 줄 알았다. 그제야 무릎을 여미고 단정히 앉아 공경하여 대답하였다. \"저렇게 귀한 손님께서 어찌하여 누추한 곳에 몸을 굽혀 오셨습니까?\"","sp":[[183,185,"P","박처사"],[203,205,"P","이득춘"]]},{"c":1,"sub":"","t":"처사가 대답하였다. \"나는 산중에 살면서 바둑 두기와 옥저 불기만 좋아하였는데, 바람결에 들으니 상공께서도 나와 같이 바둑과 옥저를 좋아하신다 하기에 구경하고자 왔습니다.\" 하니 상공이 듣고 맞수를 얻지 못해 한탄하던 차에 반가움을 헤아릴 수 없었다. \"옥저 불기야 어찌 신선의 곡조를 따라 화답하겠습니까. 그러나 변변찮은 퉁소라도 귀한 손님의 가르침을 바랄까 하여 주인이 먼저 불겠습니다.\" 하고 한 곡조를 부니 맑고 애처로운 소리가 구름 밖에서 나는 듯하였다. 그 소리가 그치자 창 앞의 모란꽃 송이가 송이송이 떨어져 화단 위에 가득하였다. 처사가 그 모습을 보고 칭찬하다가 말하였다. \"주인의 맑은 곡조만 듣고 손님이 어찌 화답하지 않으면 예의가 아닐 것입니다.\"","sp":[[0,2,"P","박처사"],[54,56,"P","이득춘"],[100,102,"P","이득춘"],[305,307,"P","박처사"]]},{"c":1,"sub":"","t":"하고 그 옥저를 불어 화답하니 그 소리가 매우 맑고 애처로워 푸른 하늘에서 나는 듯하였다. 청학과 백학이 그 소리를 듣고 춤을 추고, 선동(仙童)도 내려와 앞에서 넘노는 듯하더니, 소리가 그치자 창 앞에 떨어졌던 모란꽃 송이가 다시 피어 흐드러졌다. 상공이 그 모습을 보고 크게 칭찬하였다. \"나 같은 둔한 재주라도 세상 사람이 보고 칭찬하지 않는 이가 없었는데, 나의 퉁소는 불면 꽃송이만 떨어지더니 신선의 퉁소 소리는 봉황이 날아들고 떨어진 꽃이 다시 만발하니, 옛날 장자방(張子房)의 곡조라도 견주지 못하겠습니다.\" 하고 이어서 서로 주인과 손님이 되어 바둑과 퉁소로 화답하며 날을 보내었다. 하루는 처사가 상공에게 청하였다. \"듣자 하니 상공께서 귀한 아드님을 두셨다 하니 보기를 청합니다.\"","sp":[[140,142,"P","이득춘"],[339,341,"P","박처사"],[343,345,"P","이득춘"],[361,363,"P","이득춘"]]},{"c":1,"sub":"","t":"상공이 시백을 부르니 명을 받고 나왔다. 처사가 자세히 보니 만고의 영웅이요 한 시대의 호걸이었다. 또 조선의 명분을 생각하니 훗날 나가서는 장수, 들어와서는 몸을 세워 한 나라의 재상이 될 기상이었다. 속으로 기쁨을 이기지 못하여 상공에게 청하였다. \"제가 상공을 찾아온 것은 다름이 아니라 한 말씀 부탁드리고자 해서입니다.\" 공이 대답하였다. \"무슨 말씀을 부탁하고자 하십니까?\" 처사가 대답하였다. \"제가 딸 하나를 두었는데 나이가 열여섯이 되도록 좋은 인연을 정하지 못하여 사방을 두루 다니며 구하던 차에, 다행히 존귀한 댁에 이르러 아드님을 보니 마음에 맞습니다. 딸이 둔하기는 하나 존귀한 댁에 들일 만하니, 외람되지만 혼인을 정하는 것이 어떻겠습니까?\"","sp":[[0,2,"P","이득춘"],[4,6,"P","이시백"],[23,25,"P","박처사"],[130,132,"P","이득춘"],[145,147,"P","이득춘"],[215,217,"P","박처사"]]},{"c":1,"sub":"","t":"상공이 생각하기를 '처사의 도덕이 저러하니 그 자식이야 어찌 민첩하지 않겠는가.' 하고 대답하였다. \"손님은 신선이요 나는 속세의 인물이니 신선과 어찌 혼인하겠습니까?\" 하니 처사가 대답하였다. \"상공은 한 나라의 일품 벼슬이요 나는 미천한 인물입니다. 귀댁에 혼인을 청하는 것이 지극히 옳지 않으나, 버리지 않으신다면 한이 없을 듯합니다.\" 상공이 즉시 혼인을 허락하니 처사도 기뻐하며 바로 혼인날을 가리니 삼월 보름께였다. 혼인을 정한 뒤에 술과 안주를 내어 서로 권하며, 청풍 부는 누각에서 바둑을 두고 명월 비친 창밖에서 옥저를 불며 날을 보내었다. 하루는 처사가 작별하고 떠나겠다고 고하니, 서로 서운함을 이기지 못하였으나 어쩔 수 없이 손을 나누어 헤어지고 처사는 산중으로 돌아갔다.","sp":[[0,2,"P","이득춘"],[11,13,"P","박처사"],[98,100,"P","박처사"],[110,112,"P","이득춘"],[192,194,"P","이득춘"],[208,210,"P","박처사"],[316,318,"P","박처사"],[374,376,"P","박처사"]]},{"c":1,"sub":"","t":"이때 상공이 일가친척을 모으고 박처사의 딸과 혼인을 정한 일을 이야기하니, 부인과 친척들이 의심하여 말하였다. \"혼인은 사람의 큰일이요 인륜에서 지극히 중한 것인데, 어찌 재상가에서 그 사람의 근본도 모르고 가볍게 허락하셨습니까?\" 상공이 웃으며 말하였다. \"내가 박처사의 딸이 재덕으로 이 세상에 이름난 줄 알기에 허락하였으니, 친척들은 쓸데없이 시비하지 말라.\" 이때 혼인날이 다가오자 혼구(婚具)를 차리고 노복들을 거느리고 길을 떠났다. 상공은 상객(上客)이 되어 시백을 데리고, 시백은 금 안장 얹은 준마에 조복을 갖추어 금강산을 찾아가니, 그 모습은 청춘 호걸의 풍채도 좋거니와 행차도 찬란하였다. 이 같은 경사에 친척들은 비웃고 조정의 의논도 어수선하였다.","sp":[[3,5,"P","이득춘"],[17,20,"P","박처사"],[42,44,"P","이득춘 부인"],[130,132,"P","이득춘"],[148,151,"P","박처사"],[230,233,"P","노복들"],[248,250,"P","이득춘"],[263,265,"P","이시백"],[272,274,"P","이시백"]]},{"c":1,"sub":"","t":"여러 날 만에 강산을 찾아 들어가니 풍경도 좋거니와 때마침 봄 석 달이었다. 좌우 산천을 둘러보니 갖가지 화초가 만발한데 벌과 나비는 펄펄 날아들어 꽃을 보고 춤을 추고, 늘어진 버들가지에는 황금 같은 꾀꼬리 우는 소리가 더욱 좋았다. 풍경을 구경하며 점점 들어가니 인적은 고요하고 갈 곳을 정할 길이 없었다[?]. 하릴없이 주막을 찾아 쉬고, 이튿날 다시 길을 떠나 산골짜기로 들어가니 인적이 없었다. 층층 바위와 깎아지른 절벽은 허공에 솟아 있고 시냇물은 골골이 잔잔히 흐르며, 비쭉새는 슬피 울어 허랑한 사람을 비웃는 듯하고 두견새는 슬피 울어 근심 있는 사람을 돋우었다. 상공이 자기 일을 생각하니 도리어 허황하여 후회가 막급하였다. 또 날이 저물어 산중에서 헤매는데 잘 새는 숲으로 들고 달은 동쪽 고개에 떠올랐다. 하릴없이 또다시 주막을 찾아 쉬고, 그 이튿날 산골짜기로 들어가니 깊은 산 외진 골짜기에 길은 끊어지고 사방을 둘러보아도 사람이 없어 물을 곳이 없었다. 기운이 다하고 주림과 목마름도 심하였다. 돌 위에 자리를 잡고 늙은 소나무에 기대어 스스로 탄식하였다. \"내 일을 생각하니 남양 초당에 눈바람 치는 속에 와룡선생(臥龍先生)을 찾아온 듯하고, 수양산 깊은 곳에 백이숙제(伯夷叔齊)를 찾아온 듯하구나.\" 하며 허랑함을 한탄하는데, 문득 산골짜기에서 소리가 나며 나무하는 아이 수십 명이 내려오거늘 상공이 반겨 말하였다.","sp":[[324,326,"P","이득춘"],[684,686,"P","이득춘"]]},{"c":1,"sub":"","t":"\"저기 가는 저 아이들아, 내 말을 잠깐 들어 보아라. 이곳이 어느 곳이며 주막은 어디 있느냐. 나그네의 아득한 마음을 인도해 주는 것이 어떻겠느냐?\" 나무하는 아이가 대답하였다. \"이 산은 금강산이요, 이 길은 박처사가 살던 골로 통하는 길입니다. 우리는 지금 박처사가 살던 골에서 나오는 길입니다.\" 공이 물었다. \"지금 처사가 집에 계시더냐?\" 아이가 대답하였다. \"박처사가 있었다는 말은 옛 노인들이 이르시기를, 수백 년 전에 어떤 사람이 나무를 얽어 집을 짓고 나무 열매를 먹으며 살았는데 별호를 박처사라 하였다고 합니다.\"","sp":[[119,122,"P","박처사"],[147,150,"P","박처사"],[182,184,"P","박처사"],[208,211,"P","박처사"],[283,286,"P","박처사"]]},{"c":1,"sub":"","t":"하고 다시 대답하였다. \"어디로 갔는지 알지 못하거니와, 지금 살아 있다는 말은 처음 듣습니다.\" 또 물었다. \"처사가 그곳에서 살던 때가 지금 몇 해나 되었느냐?\" 아이가 웃으며 대답하였다. \"거기서 산 지가 사백 년이라 하더이다.\" 하며 다시는 물어도 대답하지 않고 가버렸다. 상공이 이 말을 듣고 더욱 망극하여 하늘을 우러러 크게 웃으며 탄식하였다. \"세상에 허황한 일도 많구나.\" 탄식을 그치지 않으며 말하였다. \"이미 시작한 일이로다.\" 하릴없이 노복을 데리고 주막에 돌아와 묵는데, 시백이 아버지를 위로하였다. \"옛날 한무제(漢武帝)도 신선을 구하다가 끝내 구하지 못하고 분수(汾水)의 바람 속에서 후회가 막급하였으니, 아무리 하여도 쓸데없을 것입니다. 도리어 행차를 돌리는 것만 못합니다.\"","sp":[[63,65,"P","박처사"],[157,159,"P","이득춘"],[276,278,"P","이시백"]]},{"c":1,"sub":"","t":"하니 상공이 웃으며 말하였다. \"이미 벌인 일이라 그냥 돌아가도 남의 웃음을 면치 못할 것이요, 내일은 전안(奠雁)하는 날이니 부득이 내일만 찾아보리라.\" 하고 이튿날 노복을 데리고 다시 길을 재촉하여 한나절이 되도록 산중을 오가며 찾았다. 그날 사시(巳時) 끝 오시(午時) 초에 한 사람이 갈건(葛巾)에 베옷 차림으로 대지팡이를 짚고 미투리를 신고 흰 깃털 부채를 들고 산골짜기에서 나오니, 그 모습이 참으로 바르고 곧은 도인이었다. 반가워 눈을 씻고 다시 보니 박처사가 분명하였다. 처사가 상공을 보고 반겨 말하였다. \"나 같은 사람을 인연하여 여러 날 깊은 산 외진 골짜기에서 마음을 크게 상하셨으니 매우 면목이 없습니다.\"","sp":[[3,5,"P","이득춘"],[260,263,"P","박처사"],[272,274,"P","박처사"],[276,278,"P","이득춘"]]},{"c":1,"sub":"","t":"상공이 웃고 서로 이야기를 나누며 박처사와 함께 산중으로 들어가니, 이때는 마침 봄 삼월이라 갖가지 화초가 만발하였다. 꽃향기는 옷에 스미고[?] 벌과 나비는 펄펄 날아 꽃을 보고 반기는 듯하며, 늙은 소나무는 늘어지고 버들은 봄빛을 띠었는데, 황금 같은 꾀꼬리는 가는 버들 사이를 찬란히 오락가락 지저귀며 허황한 사람을 조롱하는 듯하였다. 상공이 생각하기를 속세를 떠나 선경에 오른 것 같았다. 처사가 상공을 대하여 말하였다. \"저는 본래 가난하여 깨끗한 객실이 없으니 잠깐 돌 위에 앉으십시오.\" 하고 높이 늘어진 소나무 밑에 돌 평상을 깨끗이 쓸고 자리를 정해 주었다. 상공이 돌 평상에 앉아 수십 일 동안 만나지 못하여 고생이 막심하던 일을 이야기하며 서로 담화하는데, 처사가 말하였다.","sp":[[0,2,"P","이득춘"],[19,22,"P","박처사"],[191,193,"P","이득춘"],[222,224,"P","박처사"],[226,228,"P","이득춘"],[322,324,"P","이득춘"],[379,381,"P","박처사"]]},{"c":1,"sub":"","t":"\"이같이 궁벽한 산중이라 예절을 다 갖출 수 없으니 황공하기 그지없거니와, 혼례를 간략히 치르겠습니다.\" 하고 혼례를 차리는데, 상공은 시백을 데리고 교배석(交拜席)에 나와 두 사람이 전안을 마친 뒤, 처사가 두 사람을 인도하여 안채로 들어가고 상공은 돌 평상으로 나와 앉았다. 이윽고 처사가 나와 송화주(松花酒)를 내오며 말하였다. \"산중이라 별다른 맛이 없으니 허물하지 마십시오.\" 서너 잔을 권한 뒤에 노복들을 차례로 먹이고 상공에게 다시 권하니, 술이 독하여 기분이 좋더니 한참 뒤에 깨어 보니 날이 이미 밝아 있었다. 처사를 청하여 말하였다. \"어제 먹은 술은 참으로 인간의 술이 아니요, 과연 신선의 술입니다.\"","sp":[[72,74,"P","이득춘"],[76,78,"P","이시백"],[113,115,"P","박처사"],[137,139,"P","이득춘"],[160,162,"P","박처사"],[228,231,"P","노복들"],[241,243,"P","이득춘"],[295,297,"P","박처사"]]},{"c":1,"sub":"","t":"처사가 웃으며 말하였다. \"송화주 한 잔에 그대가 취하셨습니까?\" 상공이 대답하였다. \"신선의 좋은 술 한 잔이 참으로 과하였습니다.\" 하며 서로 이야기하다가 이날 떠나기를 청하니 처사가 말하였다. \"이 산중은 길이 험하니 이번 길에 딸을 아주 데리고 가십시오.\" 하거늘 상공이 그 말을 따라 \"그렇게 하겠습니다.\" 하고 길을 차리는데, 신부의 얼굴을 비단 적삼으로 가려 온몸을 감추어 보지 못하게 하고 처사가 상공에게 말하였다. \"데리고 가신 뒤에 다시 만납시다.\"","sp":[[0,2,"P","박처사"],[37,39,"P","이득춘"],[101,103,"P","박처사"],[152,154,"P","이득춘"],[226,228,"P","박처사"],[230,232,"P","이득춘"]]},{"c":1,"sub":"","t":"하거늘 상공이 손을 나누어 헤어진 뒤 신부를 데리고 골 어귀로 나오니 해가 서산에 지고 있었다. 주막을 찾아 들어가 상공과 신부와 세 사람이 한 방에 드니, 신부가 얼굴을 가렸던 비단 적삼을 벗었다. 그제야 비로소 상공과 시백이 신부의 얼굴을 보니, 모양은 말할 것도 없고 얼굴이 얽은 데다 더러운 때가 줄줄이 맺혀 있었다. 눈은 달팽이 눈구멍 같고, 코는 깊은 산 외진 골짜기의 험한 바위 같고, 이마는 너무 벗어져 남극노인(南極老人) 같고, 귀는 팔 척이나 넘고, 한 팔은 늘어지고 한 다리는 짧아 비틀비틀 절뚝절뚝하니 차마 볼 수가 없었다.","sp":[[4,6,"P","이득춘"],[65,67,"P","이득춘"],[120,122,"P","이득춘"],[124,126,"P","이시백"]]},{"c":1,"sub":"","t":"상공과 시백이 한번 보고는 정신이 어지러워 마주할 마음이 없었다. 그럭저럭 밤을 새우고 길을 재촉하여 서울에 이르러 본가에 들어가니, 시부모와 친척과 부인들이 신부를 구경하러 모여 있었다. 신부가 교배석에서 내려 곁방으로 들어가 얼굴을 가린 비단 적삼을 벗어 놓으니 한 시대의 장관이요 괴이한 물건이었다. 여러 부인이 보고 이런 구경은 처음이라 하며 서로 얼굴을 쳐다보고 비웃음이 끝이 없었다. 이날 경사는 고사하고 도리어 걱정을 당한 집 같았다. 온 집안이 다 놀라 허둥대는 가운데 공의 부인이 상공을 원망하였다. \"서울에도 이름난 가문 큰 집안의 얌전하고 정숙한 처녀가 많건마는 구태여 산중까지 들어가서 저토록 흉하고 험한 것을 데려다가 남의 웃음을 면치 못하게 하십니까?\"","sp":[[0,2,"P","이득춘"],[4,6,"P","이시백"],[84,86,"P","이득춘 부인"],[171,176,"P","재상가 부인들"],[274,276,"P","이득춘 부인"],[278,280,"P","이득춘"],[309,311,"P","임금"]]},{"c":1,"sub":"","t":"상공이 크게 꾸짖었다. \"아무리 절세가인을 가려 며느리로 삼아도 여자의 행실이 없으면 집안을 망치고 몸을 망쳐 가문을 보전하지 못할 것이요, 비록 못생긴 인물이라도 덕행이 있으면 가문이 흥하여 복록을 누리는 법이오. 부인은 무슨 말씀을 그토록 가볍게 하시오. 며느리 얼굴이 비록 못생겼으나 태임과 태사(太任·太姒)의 덕행이 있을 것이오. 하늘이 돕고 신이 도와 저런 며느리를 얻었거늘 부인은 어찌 사람 볼 줄 모르는 말을 하시오. 다시는 그런 말을 꺼내지 마시오.\" 부인이 그래도 부끄러움을 머금고 대답하였다. \"자식의 의관 여부는 우리 집 흥망에 달려 있으니 무엇을 근심하겠습니까.\"[?]","sp":[[0,2,"P","이득춘"],[67,69,"P","임금"],[121,123,"P","이득춘 부인"],[215,217,"P","이득춘 부인"],[261,263,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"상공이 또 말하였다. \"그렇더라도 부인은 조심하여 박대하지 마시오. 부인이 더욱 싫어하면 자식이 어찌 화락하겠소.\" 하며 경계를 그치지 않았다. 시백은 박씨의 못생긴 모습을 보고 한결같이 미워하니 종들도 함께 박대하였다. 박씨는 그저 곁방에 있으면서 잠자기만 일삼으니, 시백이 더욱 질색하여 쫓아 보내고자 하였으나 아버지가 두려워 마음대로 하지 못하였다. 상공이 그 눈치를 알고 시백을 불러 꾸짖었다.","sp":[[0,2,"P","이득춘"],[19,21,"P","이득춘 부인"],[38,40,"P","이득춘 부인"],[81,83,"P","이시백"],[85,87,"P","박씨"],[110,112,"P","노복들"],[124,126,"P","박씨"],[151,153,"P","이시백"],[199,201,"P","이득춘"],[212,214,"P","이시백"]]},{"c":1,"sub":"","t":"\"사람의 덕행을 모르고 아름다운 얼굴만 취하면 끝내 집안을 망치는 근본이 되리라. 내 들으니 너희 내외 사이가 화락하지 못하다 하니, 어찌 몸을 닦고 집안을 다스린다 하겠느냐. 옛날 제갈량(諸葛亮)의 아내 황부인은 비록 인물이 못났으나 재덕을 겸비하였으니, 공명이 그 부인을 얼굴이 박색이라 버렸다면 풍운을 부리는 재주를 누구에게 배워 영웅호걸이 되었겠느냐. 네 아내도 비록 못생겼으나 재덕이 있고 눈과 달 같은 절개와 비범한 재주가 있을 것이니 부디 소홀히 여기지 마라. 부모가 사랑하면 자식도 따라 사랑하는 법이니, 내가 사랑하는 사람을 박대하면 이는 부모를 모르는 것이다. 부디 각별히 조심하여 예법을 어기지 마라.\" 하시니 시백이 다 듣고 머리를 조아리며 사죄하였다.","sp":[[116,118,"P","이득춘 부인"],[150,152,"P","이득춘 부인"],[353,355,"P","이시백"]]},{"c":1,"sub":"","t":"\"소자가 사람을 알아보지 못하고 인륜을 그르쳤으니 죄가 만 번 죽어도 아깝지 않습니다. 다시야 어찌 가르침을 저버리겠습니까?\" 하니 상공이 말하였다. \"네가 그리 알거든 오늘부터 부부가 화락하게 하라.\" 하시니 시백이 명을 받고 어길 길이 없어, 없던 정도 있는 체하고 마음을 억지로 참으며 안채에 들어가 박씨를 대하였다. 그러나 아버지의 가르침은 까맣게 잊히고 미운 마음이 저절로 일어났다. 등잔 뒤에서 부채로 얼굴을 가리고 밤을 걱정으로 지내다가, 이윽고 닭 우는 소리가 나자 즉시 나와 부모께 문안하니, 상공이야 어찌 이런 줄을 알겠는가.","sp":[[74,76,"P","이득춘"],[118,120,"P","이시백"],[171,173,"P","박씨"],[285,287,"P","이득춘"]]},{"c":1,"sub":"","t":"상공이 또 종들을 꾸짖었다. \"내 들으니 너희가 어찌 상전을 몰라보고 업신여긴다 하니, 만일 다시 그런 말이 들리면 너희를 각별히 엄하게 다스릴 것이니 알아서 행동하라.\" 하시니 종들이 황공하여 사죄하였다. 이때 부인이 박씨를 미워하여 계화(桂花)를 불러 말하였다. \"집안 운이 불행하여 허다한 사람 가운데 저런 것을 며느리로 삼았구나. 저런 데다 게으르고 잠만 자고, 바느질 같은 여자 일은 아예 뒷전이라 밥만 배가 터지게 먹고 하는 일이 무엇이 있느냐. 매사가 저러하니 어디 쓰겠느냐. 아침저녁 밥도 조금씩만 주어라.\"","sp":[[0,2,"P","이득춘"],[6,8,"P","노복들"],[100,102,"P","노복들"],[119,121,"P","이득춘 부인"],[123,125,"P","박씨"],[132,134,"P","계화"]]},{"c":1,"sub":"","t":"하며 수많은 험담을 늘어놓고 구박이 심하니 위아래 친척도 다 화목하지 못하였다. 박씨는 여러 사람의 구박을 웃어넘기고 있다가, 하루는 시비(侍婢) 계화를 불러 말하였다. \"대감께 여쭐 말씀이 있으니 바깥채에 나가 그 연유를 여쭈어라.\" 하니 계화가 명을 받고 즉시 나가 그 말을 상공께 고하였다. 상공이 바로 들어가시니 박씨가 반갑게 맞이한 뒤에 한숨을 쉬며 상공께 여쭈었다. \"박복한 인물이 얼굴과 모양이 못나서 시부모님께 저녁에는 잠자리를 보살피고 아침에는 문안드리는 일을 남과 같이 하지 못하니 불효가 막대하거니와, 부부의 즐거움이 없고 집안 식구들과 화목하지 못하니 쓸모없는 물건이라 할 만합니다. 없는 자식으로 여기시고 후원에 초당 몇 칸을 지어 주시면 홀로 거처하며 마음의 근심을 덜까 합니다.\"","sp":[[45,47,"P","박씨"],[82,84,"P","계화"],[96,98,"P","이득춘"],[135,137,"P","계화"],[156,158,"P","이득춘"],[166,168,"P","이득춘"],[179,181,"P","박씨"],[201,203,"P","이득춘"]]},{"c":1,"sub":"","t":"말을 마치고 슬피 눈물을 흘리니, 상공이 그 모습을 보고 어찌 불쌍히 여기지 않겠는가. 박씨를 대하여 눈물을 머금고 말하였다. \"자식이 못나서 내 가르침을 듣지 않고 이같이 박대하니, 이는 다 내가 밝지 못한 탓이로다. 그러나 다시 타이를 것이니 안심하여라.\" 하시니 박씨가 그 말씀을 듣고 감격하여 여쭈었다. \"대감의 말씀은 황공하기 그지없으나, 이는 모두 며느리의 용모가 못나고 덕행이 없는 탓이니 누구를 원망하겠습니까. 지나치게 염려하지 마시고 원하는 대로 후원에 초가 몇 칸을 지어 주시기를 바랍니다.\"","sp":[[19,21,"P","이득춘"],[49,51,"P","박씨"],[150,152,"P","박씨"],[175,177,"P","이득춘"]]},{"c":1,"sub":"","t":"상공이 말하였다. \"내 그대로 하리라.\" 하시고 바깥채로 나와 시백을 불러 꾸짖었다. \"네가 끝내 신선의 딸인 줄 모르고 줄곧 내 말을 거역하니, 그래서야 어디에 쓰겠으며, 효도를 모르고서 충성이 어떻게 나겠느냐. 이러고서 몸을 닦고 집안을 다스리는 일을 어찌 하겠느냐. 아비의 명을 거역하고 그 마음을 고치지 않으면 며느리에게 불효는 고사하고 아내가 어찌 원한을 품지 않겠느냐. 여자는 마음이 좁아 훗날 일을 알 수 없을 뿐 아니라, 한 여인이 원한을 품으면 오월에도 서리가 내린다 하였으니, 그러고서야 어찌 공명을 바라겠느냐. 홀로 빈방을 지키며 한이 지극하면 목숨을 어찌할지 세상일을 미리 헤아릴 수 없다. 만일 불행한 날이 오면 첫째는 조정에 용납되지 못하고 둘째는 가문의 큰 재앙이니 어찌 근심이 없겠느냐. 너는 어떤 사람이기에 아름다운 얼굴만 생각하고 덕행을 모르느냐.\"","sp":[[0,2,"P","이득춘"],[35,37,"P","이시백"]]},{"c":1,"sub":"","t":"시백이 엎드려 사죄하였다. \"소자가 불효하여 아버님의 명을 거역하고 부부 사이의 즐거움을 끊었으니 죄가 죽어도 아깝지 않습니다. 이후에야 어찌 또 거역하겠습니까.\" 하고 나와서 생각하기를, 다시는 마음을 굳게 먹고 아버지의 명을 따르리라 하였다. 이날 박씨 방에 들어가니 눈이 저절로 감기고 얼굴을 보면 기절할 지경이었다. 아무리 마음을 고치자 한들 그 얼굴을 보고서야 속이 온전하겠는가. 겨우 닭 우는 소리를 기다려 나왔다. 하루는 상공이 하릴없이 후원에 초당을 지어 시비 계화와 함께 거처하게 하니, 박씨의 가련한 모습은 차마 볼 수 없었다.","sp":[[0,2,"P","이시백"],[141,143,"P","박씨"],[211,213,"P","임금"],[243,245,"P","이득춘"],[263,268,"P","계화"],[282,284,"P","박씨"]]},{"c":1,"sub":"","t":"이때 전하께서 상공의 총명함을 아끼시어 일품 벼슬을 높여 주시고, 내일 입궐하라는 명을 내리셨다. 상공이 근심하여 말하였다. \"조복은 헌것은 빛이 바래고 새것은 아직 준비하지 못하였는데, 내일 입궐하라 하시니 어찌 하룻밤 사이에 조복을 준비하겠소.\" 하시며 걱정을 그치지 않으시니 부인이 말하였다. \"사세가 급하니 바느질 잘하는 사람을 얻어 어떻게든 지어 봅시다.\" 하며 의논이 분분하였다. 이때 시비 계화가 이 말을 듣고 초당에 들어가 박씨께 상공의 벼슬이 오른 일과 조복 때문에 걱정하며 의논이 분분하던 이야기를 고하니, 박씨가 듣고 계화에게 말하였다. \"일이 급하거든 조복 지을 감을 가져오너라.\"","sp":[[3,5,"P","임금"],[8,10,"P","이득춘"],[55,57,"P","이득춘"],[157,159,"P","이득춘 부인"],[222,227,"P","계화"],[245,247,"P","박씨"],[249,251,"P","이득춘"],[294,296,"P","박씨"],[301,303,"P","계화"]]},{"c":1,"sub":"","t":"하니 계화가 이 말을 듣고 더욱 희한하게 여겨 박씨의 얼굴을 다시 보고 나와 상공께 여쭈었다. 상공이 듣고 크게 기뻐하며 말하였다. \"내 며느리는 신선의 딸이라 반드시 원하는 일을 해낼 재주가 있으리라.\" 하고 조복감을 급히 갖다 주라 하시니, 상공의 부인과 여러 부인이 비웃었다. \"제 모양이 그러한데 무슨 재주가 있겠습니까. 옷감만 버릴 것이니 보내지 않는 것이 옳습니다.\" 하고 의논이 분분하니 상공이 크게 꾸짖었다. \"속담에 이르기를 형산(荊山)의 백옥이 진흙에 묻혀 있어도 안목이 없어 알아보는 이가 없다 하였으니, 부인은 남의 타고난 마음을 그토록 분명히 아는 듯 가볍게 말하시오. 박씨는 본래 녹록한 여자가 아니니 급히 보내시오.\"","sp":[[3,5,"P","계화"],[26,28,"P","박씨"],[43,45,"P","이득춘"],[53,55,"P","이득춘"],[137,139,"P","이득춘"],[141,143,"P","이득춘 부인"],[145,150,"P","재상가 부인들"],[224,226,"P","이득춘"],[294,296,"P","이득춘 부인"],[332,334,"P","박씨"]]},{"c":1,"sub":"","t":"하거늘 부인이 대감의 말씀을 거역하지 못하여 들여보내고 밤낮 걱정으로 지냈다. 이때 옷감을 가지고 들어가 박씨께 드리니 박씨가 말하였다. \"이 옷은 혼자 지을 옷이 아니니 일을 도울 사람을 불러 오너라.\" 하니 계화가 이 말씀을 또 상공께 고하자 상공이 즉시 사람을 들여보냈다. 박씨가 등촉을 밝히고 조복을 짓는데, 월궁의 항아가 계수나무 꽃을 고르는 듯[?] 열 사람이 할 일을 혼자 하룻밤 사이에 다 하였다. 앞에는 봉황, 뒤에는 청학을 수놓았는데 봉황은 춤을 추고 청학은 나는 듯하였다. 함께 바느질하던 사람들이 박씨의 솜씨를 보고 탄복하여 말하였다. \"우리는 우러러보아도 미치지 못하겠다.\" 박씨가 즉시 계화에게 명하여 조복을 상공께 올리니 상공이 칭찬하였다. \"이는 신선의 솜씨요 인간 사람의 재주가 아니다.\" 하시니 그제야 부인도 보고 입이 마르도록 크게 칭찬하였다.","sp":[[4,6,"P","이득춘 부인"],[8,10,"P","이득춘"],[59,61,"P","박씨"],[67,69,"P","박씨"],[118,120,"P","계화"],[130,132,"P","이득춘"],[138,140,"P","이득춘"],[156,158,"P","박씨"],[290,292,"P","박씨"],[335,337,"P","박씨"],[342,344,"P","계화"],[355,357,"P","이득춘"],[363,365,"P","이득춘"],[411,413,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"이튿날 상공이 조복을 입고 대궐에 들어가 숙배하니, 임금께서 공의 조복을 한참 보시고 가까이 불러 물으셨다. \"경의 조복은 누가 지었는가?\" 공이 아뢰었다. \"신의 며느리가 지었습니다.\" 임금께서 또 말씀하셨다. \"그렇다면 저런 며느리를 두고 굶주림과 추위에 시달리게 하며 홀로 빈방을 지키게 함은 무슨 일인가?\" 공이 크게 놀라 엎드려 아뢰었다. \"황공하오나 전하께서 어찌 이토록 밝게 아십니까?\" 임금께서 말씀하셨다. \"경의 조복을 보니 뒤에 붙인 봉황은 짝을 잃고 우는 형상이 분명하기에 짐작하고 묻는 것이다.\" 하시니 공이 사례하였다. \"신이 밝지 못한 탓입니다.\"","sp":[[4,6,"P","이득춘"],[29,31,"P","임금"],[105,107,"P","임금"],[202,204,"P","임금"],[224,226,"P","임금"]]},{"c":1,"sub":"","t":"임금께서 그 사정을 자세히 물으시니 공이 아뢰었다. \"신의 며느리가 얼굴이 못생겨서 못난 자식이 아비의 가르침을 듣지 않고 서로 화락하지 못하는 것입니다.\" 임금께서 또 물으셨다. \"빈방을 홀로 지키는 것은 그렇다 하거니와, 날마다 굶주림과 추위를 견디지 못하여 눈물로 세월을 보내는 것은 무슨 일인가?\" 하시니 공이 황공함을 이기지 못하여 땀이 등을 적시며 머뭇거리다가 아뢰었다. \"신이 바깥채에 거처하여 안살림은 자세히 알지 못하오나, 신이 밝지 못한 탓이니 황공하기 그지없습니다.\" 임금께서 또 말씀하셨다.","sp":[[0,2,"P","임금"],[88,90,"P","임금"],[273,275,"P","임금"]]},{"c":1,"sub":"","t":"\"경의 며느리가 얼굴은 곱지 못하나 영웅의 재주가 있는 듯하니 부디 박대하지 말라.\" 하시며 명을 내리셨다. \"날마다 백미 서 말씩 줄 것이니 이것으로 먹게 하되 한 끼에 한 말씩 밥을 지어 먹이고, 경의 집안사람들도 박대하지 못하게 각별히 단속하고 천대하지 못하게 하라.\" 하시니 공이 명을 받들고 집에 돌아와 집안사람들을 모으고 임금의 분부를 낱낱이 전한 뒤 시백을 크게 꾸짖었다.","sp":[[186,188,"P","임금"],[203,205,"P","이시백"]]},{"c":1,"sub":"","t":"\"부모의 마음을 편하게 하는 것은 자식의 효성이요, 임금을 도와 나라를 태평하게 하고 백성을 편안하게 하는 것은 신하의 충성이다. 너 같은 자식은 아비의 가르침을 듣지 않고 네 마음대로 하다가 아비에게 황송한 처분이 미치게 하고 동료들에게 책망을 당하게 하니, 이는 너의 불효다. 너는 어떤 놈이기에 부모에게 효행은 못할망정 가르침을 이같이 거역하느냐. 그런 불효가 어디 또 있겠느냐.\" 하시며 큰 소리로 꾸짖으시니 시백이 엎드려 대답하였다. \"아버님의 가르침을 거역하여 이 지경을 당하고 이토록 노하시게 하였으니 더욱 황공하기 그지없습니다.\"","sp":[[29,31,"P","임금"],[233,235,"P","이시백"]]},{"c":1,"sub":"","t":"공이 분을 이기지 못하여 말없이 있다가 한참 뒤에 말하였다. \"네가 내 영을 거역하면 첫째는 나라에 불충이요, 둘째는 부모에게 막대한 불효이니 각별히 조심하라.\" 하시니 그 뒤로는 시백과 집안사람들이 박씨의 말을 조금도 거역하지 못하였다. 박씨에게 날마다 서 말씩 밥을 지어 주니 거뜬히 다 먹으므로 보는 사람들이 여장군이라 하였다. 하루는 박씨가 계화를 시켜 대감께 여쭐 말씀이 있다고 고하니, 공이 즉시 들어와 박씨에게 말하였다. \"무슨 말이 있느냐?\" 박씨가 무릎을 여미고 단정히 앉아 여쭈었다.","sp":[[101,103,"P","이시백"],[112,114,"P","박씨"],[134,136,"P","박씨"],[191,193,"P","박씨"],[195,197,"P","계화"],[202,204,"P","이득춘"],[232,234,"P","박씨"],[256,258,"P","박씨"]]},{"c":1,"sub":"","t":"\"집안 형편이 넉넉지 못하여 몹시 송구하오나 제 말대로 해 주시기를 바랍니다. 종로에 하인을 보내면 여러 사람이 말을 팔려고 모여 있을 것입니다. 여러 말 가운데 작은 망아지가 있는데 비루먹고 여위어 모양은 볼 것이 없으나, 그렇다 하지 마시고 삼백 냥을 주고 사 오라 하십시오.\" 하거늘 상공이 들으니 그 말이 허황하였으나 박씨는 보통 사람이 아니므로 바깥채로 나와 노복을 불러 분부하였다.","sp":[[162,164,"P","이득춘"],[182,184,"P","박씨"]]},{"c":1,"sub":"","t":"\"종로에 나가면 말 장수들이 말을 팔려고 있을 것이니 그 가운데 비루먹고 여윈 말을 사 오너라.\" 하고 돈 삼백 냥을 주시니, 노복들이 명을 받고 나와 서로 말하였다. \"대감께서 무슨 까닭으로 비루먹고 여윈 말을 삼백 냥이나 주고 사 오라 하시는지 참으로 괴이하다.\" 하고 삼백 냥을 가지고 종로에 나가 보니, 과연 말 장수들이 좋은 말 여러 필을 가지고 있었는데 그 가운데 비루먹고 여윈 망아지가 있었다. 임자를 찾아 말하였다. \"이 말값이 얼마나 되느냐?\"","sp":[[9,13,"P","말 장수"],[71,74,"P","노복들"],[95,97,"P","이득춘"],[177,181,"P","말 장수"]]},{"c":1,"sub":"","t":"임자가 대답하였다. \"값은 오백 닢이거니와, 이 가운데 천리마가 수두룩한데 이런 변변찮은 망아지를 사서 무엇 하려고 하시오?\" 하며 좋은 말을 가져가라 하니 노복들이 대답하였다. \"우리 대감의 분부가 이러하시기에 이 망아지를 사려는 것이다.\" 말 장수가 말하였다. \"그러면 엽전 닷 냥만 주고 사 가시오.\" 하니 노복들이 말하였다. \"우리 대감 분부에 삼백 냥을 다 주고 사 오라 하셨기에 왔으니 삼백 냥을 받고 망아지를 다오.\" 말 장수가 대답하였다. \"이 망아지 본값이 닷 냥이니 어찌 지나친 값을 받겠소. 참으로 그 까닭을 모르겠소.\"","sp":[[88,91,"P","노복들"],[104,106,"P","이득춘"],[136,140,"P","말 장수"],[175,178,"P","노복들"],[190,192,"P","이득춘"],[241,245,"P","말 장수"]]},{"c":1,"sub":"","t":"노복들이 말하였다. \"우리 대감의 분부대로 주는 것이니 염려 말고 받아라.\" 하며 주었으나 말 장수는 그 까닭을 알지 못하여 굳이 사양하고 받지 않았다. 종들이 다투다 못하여 억지로 백 냥만 주고 이백 냥은 숨겨 나누어 가진 뒤, 말을 끌고 돌아와 상공께 아뢰었다. 상공이 보시고 망아지 사 온 일을 박씨에게 알리고 말을 보이니, 박씨가 말을 한참 보다가 상공께 여쭈었다. \"이 말값은 삼백 냥이 본값이니 제값을 주어야 쓸 것인데, 무지한 노복들이 백 냥만 주고 이백 냥은 저희끼리 나누어 먹고 말 장수에게 주지 않았으니 쓸 데가 없습니다. 도로 가져다 말 장수에게 주라 하십시오.\"","sp":[[0,3,"P","노복들"],[15,17,"P","이득춘"],[51,55,"P","말 장수"],[86,88,"P","노복들"],[139,141,"P","이득춘"],[149,151,"P","이득춘"],[168,170,"P","박씨"],[185,187,"P","박씨"],[199,201,"P","이득춘"],[246,249,"P","노복들"],[277,281,"P","말 장수"],[310,314,"P","말 장수"]]},{"c":1,"sub":"","t":"상공이 이 말을 듣고 박씨의 신통함에 탄복하고, 나와서 노복들을 불러 크게 꾸짖었다. \"너희가 말값 삼백 냥 가운데 이백 냥은 숨기고 백 냥만 주었으니, 상전을 속인 죄는 나중에 받으려니와 숨긴 이백 냥을 가지고 가서 말 장수를 찾아 주고 오너라. 그렇지 않으면 너희는 목숨을 보전하지 못할 것이니 바삐 찾아 주고 오너라.\" 하니 노복들이 상공께 사죄하였다. \"이처럼 밝게 아시니 어찌 속이겠습니까. 과연 대감 분부대로 삼백 냥을 모두 주었더니 말 본값이 닷 냥이라며 끝내 받지 않고 사양하기에 이백 냥을 숨겼던 것입니다. 이같이 신통하게 아시니 저희의 죄는 만 번 죽어도 아깝지 않습니다.\"","sp":[[0,2,"P","이득춘"],[12,14,"P","박씨"],[31,34,"P","노복들"],[122,126,"P","말 장수"],[156,158,"P","임금"],[185,188,"P","노복들"],[190,192,"P","이득춘"],[227,229,"P","이득춘"]]},{"c":1,"sub":"","t":"하고 즉시 이백 냥을 가지고 가서 말 장수를 불러 말하였다. \"어허, 이 몹쓸 사람아. 주는 돈을 마다하고 받지 않아서 우리가 상전에게 중죄를 당하게 되었으니 어찌 분하지 않겠느냐.\" 억지로 이백 냥을 주고 돌아와 다시 여쭈었다. \"말 임자를 찾아 주고 왔습니다.\" 상공이 즉시 들어가 박씨에게 이 말을 전하니 박씨가 여쭈었다. \"이 말을 먹이되 하루 한 번 보리 서 되와 깨 서 되씩 죽을 쑤어 삼 년 동안 단단히 일러 먹이게 하십시오.\" 하니 상공이 허락하고 노복들에게 분부하였다.","sp":[[19,23,"P","말 장수"],[149,151,"P","이득춘"],[160,162,"P","박씨"],[170,172,"P","임금"],[174,176,"P","박씨"],[250,252,"P","이득춘"],[259,262,"P","노복들"]]},{"c":1,"sub":"","t":"한편 이때 시백은 아버지의 명을 거역하지 못하여 부부가 함께 자려고 초당에 들어가지만, 얼굴과 못생긴 모습을 보면 마음이 저절로 편치 않았다. 후원에 초당을 지었는데 당호를 피화당(避禍堂)이라 하였다. 박씨는 날마다 계화와 더불어 나무를 심었는데, 동쪽에는 청색 기운에 응하여 후토[?]로 북을 돋우고, 남쪽에는 붉은 기운에 응하여 붉은 흙으로 북을 돋우고, 서쪽에는 흰 기운에 응하여 흰 흙으로 북을 돋우고, 북쪽에는 검은 기운에 응하여 검은 흙으로 북을 돋우고, 가운데에는 누런 기운에 응하여 누런 흙으로 북을 돋우어 오색으로 심어 놓았다. 계화를 시켜 때맞추어 물을 주니 그 나무가 나날이 자라 모양이 엄숙하고 신기하였다. 무수한 바람과 구름의 조화와 위엄이 엄숙한 가운데 나뭇가지는 용이 서린 듯 범이 호령하는 듯하고, 온갖 새와 바람이 일어나면 변화가 끝이 없으니, 그 신기한 일은 귀신도 헤아리지 못하는데 무식한 사람이야 어찌 알겠는가.","sp":[[6,8,"P","이시백"],[113,115,"P","박씨"],[121,123,"P","계화"],[305,307,"P","계화"]]},{"c":1,"sub":"","t":"이때 상공이 계화를 불러 물었다. \"요사이 부인이 무엇을 일삼더냐?\" 계화가 대답하였다. \"부인께서 후원에 갖가지 나무를 심었는데 이리이리 하시고, 저더러 물을 길어다 주라 하셨습니다.\" 공이 듣고 크게 기뻐하여 계화를 데리고 구경하러 후원에 들어가 좌우를 살펴보니, 갖가지 나무가 사방에 무성하여 엄숙한 기운에 바로 보기 어려웠다. 상공이 놀라 겨우 정신을 가다듬고 자세히 살펴보니, 나무는 용과 범이 변화를 부리고 가지는 무수한 뱀이 서린 듯하여 변화가 끝이 없었다. 상공이 크게 놀라 탄식하였다. \"이 사람은 과연 신인(神人)이로다. 여자로서 영웅의 큰 계략을 지녔으니 그 신묘한 재주는 헤아릴 수 없구나.\"","sp":[[3,5,"P","이득춘"],[7,9,"P","계화"],[24,26,"P","이득춘 부인"],[39,41,"P","계화"],[51,53,"P","이득춘 부인"],[119,121,"P","계화"],[187,189,"P","이득춘"],[264,266,"P","이득춘"]]},{"c":1,"sub":"","t":"하고 박씨에게 물었다. \"저 나무는 무슨 일로 심었으며, 이 집 당호를 피화당이라 하였으니 무슨 까닭인지 모르겠구나.\" 하시니 박씨가 여쭈었다. \"길흉화복은 인간에 늘 있는 일이니, 훗날 혹 어떤 일이 있더라도 이 나무로 막을 것이기에 사방에 심었습니다.\" 공이 그 말을 듣고 놀라 그 까닭을 물으니 박씨가 여쭈었다. \"이 또한 하늘의 운수이니 어찌 하늘의 운수를 누설하겠습니까. 훗날 자연히 아실 것입니다.\" 하거늘 상공이 탄식하였다. \"너는 참으로 나 같은 사람의 며느리가 되기 아깝고, 팔자가 기박하여 저러한 인물을 내 자식이 몰라보고 부부간에 화락하지 못하여 세월을 헛되이 보내니 참으로 원통하고 분하구나.\"","sp":[[3,5,"P","박씨"],[71,73,"P","박씨"],[168,170,"P","박씨"],[234,236,"P","이득춘"]]},{"c":1,"sub":"","t":"박씨가 여쭈었다. \"제 용모와 몸이 남과 같지 못하여 부부간에 금슬의 즐거움이 없으니 이는 다 제 죄입니다. 누구를 원망하겠습니까. 제 소원은 다만 남편이 과거에 급제하여 부모께 효도를 극진히 하고, 몸을 세워 이름을 떨치거든 나라를 충성으로 섬기며, 다른 가문에서 아내를 얻어 자손을 두고 오래도록 평안하면 지금 죽어도 남은 한이 없을까 합니다.\" 하거늘 공이 그 말을 듣고 그 애처로운 마음을 더욱 불쌍히 여겨 눈물을 흘리시니, 박씨가 그 모습을 보고 위로하였다. \"귀하신 몸을 보중하십시오. 언제라도 화락할 때가 없겠습니까. 너무 근심하지 마십시오. 아버님께서 싫어하시면 남편의 허물이 드러나 마을 사람들이 불효한다 할 것이니, 제 허물로 남편에게 악명이 돌아갈까 두렵습니다.\"","sp":[[0,2,"P","박씨"],[242,244,"P","박씨"]]},{"c":1,"sub":"","t":"상공이 들으시고 도량이 넉넉하고 효성이 지극함을 더욱 입이 마르도록 칭찬하셨다. 한편 이때 망아지를 먹인 지 이미 삼 년이 되었다. 말은 준마가 되었고 걸음은 나는 범 같았다. 박씨가 상공께 여쭈었다. \"계유년 섣달 스무사흗날 오시에 중국에서 칙사가 나올 것이니, 이 말을 가지고 가서 칙사 오는 길가에 매어 두면 칙사가 보고 사기를 청할 것입니다. 삼만 냥으로 값을 정하여 팔아 오라 하십시오.\" 상공이 칭찬하시고 그날을 기다렸더니 과연 그날 칙사가 나온다 하였다. 노복에게 명하여 말을 끌고 가서 칙사 오는 길가에 매어 두었더니, 칙사가 오다가 과연 그 말을 보고 물었다. \"이 말이 팔 말이며 값은 얼마나 되느냐?\"","sp":[[0,2,"P","이득춘"],[99,101,"P","박씨"],[103,105,"P","이득춘"],[136,138,"P","칙사"],[160,162,"P","칙사"],[176,178,"P","칙사"],[223,225,"P","이득춘"],[249,251,"P","칙사"],[280,282,"P","칙사"],[299,301,"P","칙사"]]},{"c":1,"sub":"","t":"대답하였다. \"팔 말이고 값은 삼만 냥입니다.\" 칙사가 크게 기뻐하여 삼만 냥을 많다 하지 않고 즉시 실어다 주고 사 갔다. 노복이 돌아와 그 사연을 고하니, 공이 삼만 냥을 순식간에 얻어 살림이 저절로 넉넉해졌다. 기뻐하며 박씨에게 물었다. \"말값은 받았으나 그 신묘한 일은 알지 못하겠구나.\" 박씨가 공경히 대답하였다. \"그 말은 곧 천리마입니다. 조선은 작은 나라라 알아볼 사람이 없을 뿐더러 땅이 좁아 쓸 데가 없고, 중국은 땅이 넓으니 곧 만 리를 달릴 것입니다. 칙사는 준마를 알아보기에 삼만 금을 아끼지 않고 사 갔지만, 조선에서야 누가 값을 알며 준마를 알아보겠습니까.\"","sp":[[27,29,"P","칙사"],[126,128,"P","박씨"],[166,168,"P","박씨"],[265,267,"P","칙사"]]},{"c":1,"sub":"","t":"상공이 그 말을 듣고 탄복하였다. \"비록 여자이나 앉아서 만 리 밖을 내다보니 참으로 아깝구나. 만일 남자였더라면 귀하게 될 것을, 이미 여자의 몸이니 어찌 한탄스럽지 않겠느냐.\" 하였다. 한편 이때 나라가 태평하고 백성이 편안하며 해마다 풍년이 들자, 인재를 뽑고자 대과를 보이게 되었다. 시백이 듣고 과거를 보러 시험장에 들어가려 하였는데, 그날 밤 박씨가 한 꿈을 꾸었다. 후원 연못 가운데 화초가 만발하고 벌과 나비가 날아드는데, 그 가운데 청룡이 굼실굼실 놀다가 여의주를 입에 물고 오색구름을 헤치고 옥경(玉京)으로 오르는 것이 보였다. 박씨가 잠을 깨어 생각하니 한바탕 큰 꿈이었다. 그로 인해 잠을 이루지 못하고 이리저리 뒤척이며 제 신세를 생각하니 여자의 몸이 가련하였다. 또 꿈을 생각하니 연못의 연적이 여의주임이 분명하였다. 이럭저럭 동쪽이 밝아 오자 꿈에 보이던 백옥 연적을 찾아보니 과연 연적 하나가 있었다. 반가이 주워다 놓고 즉시 계화를 시켜 시백에게 전갈하기를, 사랑에 나가 서방님께[?] 여쭈어 잠깐 들어오시라 하였다. 계화가 명을 받고 바깥채로 나가 그 사연을 고하니 시백이 듣고 얼굴빛을 바로 하며 말하였다.","sp":[[0,2,"P","이득춘"],[163,165,"P","이시백"],[198,200,"P","박씨"],[306,308,"P","박씨"],[479,481,"P","계화"],[486,488,"P","이시백"],[531,533,"P","계화"],[559,561,"P","이시백"]]},{"c":1,"sub":"","t":"\"무슨 말이 있기에 대장부 과거 길을 지체하게 하느냐?\" 계화가 무안하여 들어와 그대로 고하니, 박씨가 다시 계화를 시켜 전갈하였다. \"잠깐 들어오시면 드릴 것이 있으니 한번 수고를 아끼지 마십시오.\" 시백이 크게 노하여 말하였다. \"요망한 계집이 장부의 길을 막으니 이런 당돌한 일이 어디 있느냐.\" 앉지도 서지도 못하고 안절부절하다가 계화를 잡아내어 큰 매로 십여 대를 엄하게 치니, 계화가 벌을 받고 울며 들어가 고하였다. 박씨가 눈물을 흘리며 슬피 울다가 말하였다. \"내 죄로 네가 중한 벌을 받았으니 이같이 분한 일이 어디 있겠느냐.\"","sp":[[32,34,"P","계화"],[54,56,"P","박씨"],[61,63,"P","계화"],[113,115,"P","이시백"],[189,191,"P","계화"],[217,219,"P","계화"],[240,242,"P","박씨"]]},{"c":1,"sub":"","t":"슬피 탄식하고 연적을 계화에게 주며 전갈하였다. \"이 연적에 물을 넣어 시험장에 들어가거든 그 물로 먹을 갈아 글을 지어 바치면 장원급제할 것입니다. 몸을 세우고 이름을 떨치거든 부모님께 영화가 되게 하시고, 가문을 빛낸 뒤에는 나 같은 인물은 생각하지 마시고 다른 가문의 얌전하고 정숙한 여인을 얻어 평생을 홀로 즐기십시오.\" 하니 시백이 다 듣고 연적을 받아 보니 천하의 보배였다. 도리어 잘못을 뉘우치고 스스로 꾸짖으며 말하였다. \"지난 일은 말할 것 없으니 풀어 버리시고 안심하고 지내시면 사과하는 날이 있을 것입니다.\"","sp":[[12,14,"P","계화"],[154,156,"P","임금"],[187,189,"P","이시백"]]},{"c":1,"sub":"","t":"하고 바로 시험장에 들어가 연적의 물로 먹을 갈아 단숨에 써 내려가니 한 점도 고칠 데가 없었다. 첫째로 글을 바치고 나와 방을 기다렸더니, 한참 뒤에 방목을 내걸었는데 바라보니 장원에 '한성부 이시백'이라 하였다. 춘당대(春塘臺)에 높이 앉아 신래(新來)를 부르는 소리에 장안이 진동하였다. 시백이 임금의 은혜에 감사하고 즉시 대궐에 들어가니, 대신들이 무수히 신래 진퇴를 재촉한 뒤에 은혜에 사례하는 숙배를 올렸다. 임금께서 칭찬을 그치지 않으시며 충성을 다해 나라에 보답하라 당부하시니, 시백이 다시 황공하여 두 번 절하고 집으로 돌아왔다. 머리에는 어사화를 꽂고 몸에는 비단 도포에 옥 띠를 두르고 금 안장 얹은 준마에 의젓이 앉았으니 훤칠한 풍채가 찬란하였다. 살구꽃 피는 봄바람 속 큰길 위에서 구경하는 사람들이 누구인들 사랑하고 칭찬하지 않겠는가.","sp":[[109,112,"P","이시백"],[164,166,"P","이시백"],[168,170,"P","임금"],[176,178,"P","이시백"],[235,237,"P","임금"],[276,278,"P","이시백"]]},{"c":1,"sub":"","t":"집에 돌아와 의기양양하게 즐거워할 때, 박씨는 참예도 못하고 적막한 초당에 홀로 앉아 있으니 어찌 한심하지 않겠는가. 박씨의 넓은 도량이 아니면 어찌 이 경사를 지켜보겠는가. 계화가 박씨의 모습을 차마 보지 못하여 부인께 여쭈었다. \"이런 경사에 위아래 친척이 모여 즐거워하는데 박씨 부인은 혼자 초당에 있으면서 눈물로 세월을 보내시니 제 마음도 어찌 참혹하지 않겠습니까.\" 박씨가 태연히 대답하였다. \"사람의 길흉과 영욕은 하늘에 달렸으니 이 또한 하늘의 운수다. 누구를 원망하고 누구를 탓하겠느냐.\"","sp":[[22,24,"P","박씨"],[66,68,"P","박씨"],[98,100,"P","계화"],[102,104,"P","박씨"],[120,122,"P","이득춘 부인"],[156,161,"P","박씨"],[210,212,"P","박씨"]]},{"c":1,"sub":"","t":"계화가 듣고 속으로 박씨의 넓은 마음에 거듭 탄복하였다. 한편 박씨가 친정을 떠나온 지 이미 삼 년이었다. 하루는 상공께 여쭈었다. \"제가 시집온 지 이미 삼 년인데 소식이 끊겼으니 잠깐 다녀오고자 합니다.\" 하니 상공이 듣고 크게 놀라 말하였다. \"여기서 금강산이 수백 리다. 길이 험하여 남자라도 오가기 어려운데 하물며 여자가 어찌 마음대로 오가겠느냐.\" 박씨가 다시 아뢰었다. \"저도 험한 길이 어려운 줄은 아오나 부득불 다녀올 일이 있으니 염려하지 마십시오.\"","sp":[[0,2,"P","계화"],[11,13,"P","박씨"],[35,37,"P","박씨"],[64,66,"P","이득춘"],[120,122,"P","이득춘"],[201,203,"P","박씨"]]},{"c":1,"sub":"","t":"상공이 말하였다. \"네가 부득이 간다 하니 말리지는 못하거니와, 행장은 내일 차려 줄 것이니 속히 다녀오너라.\" 하시니 박씨가 다시 아뢰었다. \"친정 가는 행장은 염려하지 마십시오. 오가는 데 사나흘이면 될 것이니 근심하지 마십시오.\" 상공은 본래 박씨의 재주를 아는지라 부득이 허락은 하였으나, 분명한 사정을 알지 못하여 속으로 근심이 되어 자고 먹는 것이 절로 편치 않았다. 박씨가 초당으로 돌아와 계화를 불러 말하였다. \"내가 친정에 잠깐 다녀올 것이니 너만 알고 말을 퍼뜨리지 마라.\" 하고 이날 삼경에 혼자 길을 떠났다. 계화가 하직하고 있었더니 사나흘 만에 과연 다녀오니, 상공이 보시고 크게 놀라고 기뻐하며 말하였다. \"너의 신기한 술법은 귀신도 헤아리지 못하겠구나. 그런데 너의 부친께서는 평안하시더냐?\"","sp":[[0,2,"P","이득춘"],[67,69,"P","박씨"],[132,134,"P","이득춘"],[139,141,"P","박씨"],[212,214,"P","박씨"],[225,227,"P","계화"],[297,299,"P","계화"],[327,329,"P","이득춘"]]},{"c":1,"sub":"","t":"박씨가 대답하였다. \"아직 평안하시고, 아무 달 아무 날에 오시겠다 하셨습니다.\" 하니 상공이 기뻐하며 처사가 오기를 기다렸다. 처사가 오겠다고 한 날이 되자 공이 홀로 앉아 기다리는데, 오색구름이 집 안에 영롱하고 맑은 옥저 소리가 구름 밖에서 들리더니, 문득 한 선관(仙官)이 백학을 타고 오색구름 가운데로 내려왔다. 자세히 보니 바로 박처사였다. 상공이 의관을 바로 하고 뜰에 내려가 맞이하여 인사를 마치고 자리를 정한 뒤, 그동안 쌓인 회포를 이야기하며 술과 안주를 내어 서로 취하도록 먹고 즐겼다. 공이 처사에게 사례하였다. \"귀한 손님을 뵈니 반가운 마음은 말할 것도 없고 미안한 마음을 헤아릴 수 없습니다.\"","sp":[[0,2,"P","박씨"],[49,51,"P","이득춘"],[58,60,"P","박처사"],[72,74,"P","박처사"],[149,151,"P","박처사"],[190,193,"P","박처사"],[197,199,"P","이득춘"],[287,289,"P","박처사"]]},{"c":1,"sub":"","t":"처사가 말하였다. \"무슨 말씀이신지, 도리어 제가 미안합니다.\" 공이 공경히 대답하였다. \"내 자식이 못나서 연분을 몰라보고 부부가 화락하지 못하기에 날마다 타일러도 아비의 명을 끝내 거역하니 어찌 불안하지 않겠습니까.\" 처사가 사례하였다. \"상공의 넓으신 덕으로 제 자식을 못생겼다 하지 않으시고 슬하에 두고 사랑하시니 감격하기 그지없습니다. 그러나 사람의 영욕은 하늘이 정한 바요 사람이 마음대로 할 바가 아니니 어찌 그것으로 근심하십니까.\" 공이 듣고 부끄럽게 여겼다.","sp":[[0,2,"P","박처사"],[124,126,"P","박처사"],[136,138,"P","이득춘"]]},{"c":1,"sub":"","t":"공이 처사와 더불어 날마다 바둑 두기와 옥저 불기로 날을 보냈는데, 하루는 처사가 피화당에 들어가 조용히 박씨에게 일렀다. \"네 액운이 다하였으니 누추한 허물을 벗어라.\" 하시고 허물을 벗고 몸을 바꾸는 술법을 가르치며 다시 일렀다. \"허물을 벗거든 누추한 허물을 버리지 말고 상공께 여쭈어 옥함을 짜 달라 하여 그 속에 넣어 간수하여라.\" 은근한 정담을 한참 나누다가 소매를 떨치고 나와 상공께 작별을 고하니, 공이 듣고 몹시 섭섭하여 만류하였으나 처사는 듣지 않고 떠나려 하였다. 공이 하릴없이 술 한 잔으로 작별하는데 처사가 공에게 말하였다. \"지금 작별하면 다시 만나기 어려우니 내내 평안하십시오.\" 하거늘 공이 듣고 대답하였다. \"어인 말씀이십니까?\"","sp":[[3,5,"P","박처사"],[42,44,"P","박처사"],[59,61,"P","박씨"],[155,157,"P","이득춘"],[218,220,"P","이득춘"],[252,254,"P","박처사"],[293,295,"P","박처사"]]},{"c":1,"sub":"","t":"처사가 말하였다. \"나도 섭섭하나 이번에 산에 들어가면 다시 나오기가 아득하여 실로 만나기 어렵겠습니다.\" 공이 하릴없이 애달프게 작별하니, 처사가 학을 타고 공중으로 올라 오색구름을 헤치고 가더니 구름이 걷히며 간 데가 없었다. 상공이 탄복하기를 그치지 않았다. 한편 이날 밤 박씨가 목욕재계하고 둔갑하여 허물을 벗었다. 날이 밝자 계화를 부르니, 계화가 들어가 보매 전에 없던 절세가인이 방 안에 앉아 있었다. 자세히 보니 아름다운 얼굴과 단정한 태도는 한번 보면 정신이 어지러워 바라보기 어려웠다. 박씨가 붉은 입술을 반쯤 열어 계화에게 말하였다. \"나는 전날의 박씨 부인인데 지금 허물을 벗고 몸이 바뀌었다. 급히 바깥채에 나가 떠벌리지 말고 대감께 여쭈어 옥함을 얻어 오게 하라.\"","sp":[[0,2,"P","박처사"],[79,81,"P","박처사"],[129,131,"P","이득춘"],[156,158,"P","박씨"],[187,189,"P","계화"],[196,198,"P","계화"],[282,284,"P","박씨"],[299,301,"P","계화"],[318,323,"P","박씨"],[364,366,"P","이득춘"]]},{"c":1,"sub":"","t":"하니 계화가 명을 받고 바깥채로 나가는데 기쁜 빛이 얼굴에 가득하였다. 상공이 이상히 여겨 바삐 물었다. \"무슨 좋은 일이 있느냐?\" 계화가 대답하였다. \"피화당에 신기한 일이 있으니 급히 가 보십시오.\" 상공이 급히 들어가 방문을 열고 보니 전에 없던 미인이 단정히 앉아 있는데, 얌전한 태도는 사람의 정신을 놀라게 하고 방 안에 향내가 코를 찔렀다. 정신을 가다듬고 자세히 보니 전날 못생겼던 박씨가 오늘은 선녀와 같았는데, 상공을 보고 오히려 부끄러운 빛을 띠었다. 공이 마음속으로 이상하고 신기함에 탄복하여 입을 다물고 말이 없으시니 계화가 여쭈었다.","sp":[[3,5,"P","계화"],[40,42,"P","이득춘"],[75,77,"P","계화"],[115,117,"P","이득춘"],[222,224,"P","박씨"],[240,242,"P","이득춘"],[303,305,"P","계화"]]},{"c":1,"sub":"","t":"\"부인께서 어젯밤에 허물을 벗으시고, 대감께 옥함을 구해 달라고 여쭈라 하셨습니다.\" 공이 듣고 기뻐하며 그제야 가까이 가서 물었다. \"네가 어찌하여 오늘 절세가인이 되었느냐?\" 박씨가 고개를 숙이고 붉은 입술을 반쯤 열어 여쭈었다. \"제가 이제야 액운이 다하였기에 누추한 허물을 벗었습니다. 옥함을 얻어 주시면 그 허물을 간수할까 합니다.\" 하거늘 공이 신기함에 탄복하고 즉시 나와 옥장이를 불러 옥함을 당장 만들어 오라 하고, 곧 시백을 불러 말하였다. \"바삐 들어가서 네 아내의 얼굴을 보아라.\"","sp":[[1,3,"P","이득춘 부인"],[21,23,"P","이득춘"],[100,102,"P","박씨"],[243,245,"P","이시백"]]},{"c":1,"sub":"","t":"하시니 시백이 듣고 돌아서며 얼굴을 찡그리고 생각하기를 '이같이 못생긴 인물을 무슨 까닭으로 보라 하시는가.' 하였다. 부모의 명을 거역하지 못하여 들어가면서도 수없이 머뭇거리는데, 계화가 바삐 나와 맞이하였다. 시백이 계화에게 물었다. \"피화당에 무슨 일이 있기에 네 얼굴에 기쁜 빛이 가득하냐?\" 계화가 여쭈었다. \"방에 들어가시면 자연히 아실 일이 있습니다.\" 하거늘 시백이 의아하여 급히 방문을 열고 보니, 못생겼던 박씨는 어디 가고 꽃과 달 같은 얌전한 여인이 앉아 있는데, 그 모습은 하늘의 선녀가 내려온 듯하여 꽃 같은 얼굴과 달 같은 자태가 사람이 아닌 듯하였다. 마음이 몹시 송구하여 말을 건네기는커녕 방에 들어가지도 못하고 도로 나와 계화에게 물었다. \"흉악하던 인물은 어디 가고 만고의 절색이 앉아 있으니 무슨 까닭이냐?\"","sp":[[4,6,"P","이시백"],[102,104,"P","계화"],[119,121,"P","이시백"],[123,125,"P","계화"],[168,170,"P","계화"],[209,211,"P","이시백"],[237,239,"P","박씨"],[365,367,"P","계화"]]},{"c":1,"sub":"","t":"계화가 대답하였다. \"전날의 박씨가 오늘 밤 절색이 되셨습니다.\" 그제야 시백이 사람 볼 줄 몰랐던 것을 절절히 후회하며 몇 해 동안 박대한 일을 생각하니 도리어 부끄러워, 바깥채로 나와 머뭇거리다가 대감께 뵈었다. 공이 말하였다. \"네 아내의 얼굴이 지금은 어떻더냐?\" 시백이 엎드려 대답하였다. \"소자가 무식한 죄를 압니다.\" 하였다. 상공이 다시 말하였다. \"사람의 영욕과 화복은 하늘에 있는 것이다. 지난 일을 생각하면 무슨 염치로 네 아내를 대하겠느냐. 어찌 지각이 그러하냐. 큰일을 이같이 하면 낭패가 되지 않겠느냐.\"","sp":[[0,2,"P","계화"],[16,18,"P","박씨"],[41,43,"P","이시백"],[112,114,"P","이득춘"],[152,154,"P","이시백"],[190,192,"P","이득춘"]]},{"c":1,"sub":"","t":"시백이 더욱 황공하여 아무 대답도 하지 못하였다. 날이 이미 저물자 시백이 박씨 방에 들어가니, 박씨가 등촉을 밝히고 얼굴빛을 바로 한 채 앉아 있었다. 시백은 감히 말을 붙이지 못하고 박씨가 먼저 말하기만 기다렸으나 끝내 입을 다물고 말이 없었다. 시백이 홀로 자책하였다. \"부인이 이같이 하는 것은 몇 해 동안 박대한 탓이로다.\" 한탄을 그치지 않았으나, 박씨는 보아도 못 본 체 들어도 못 들은 체하여 끝내 대답이 없었다. 시백이 할 수 없이 촛불 아래 앉아 있다가 닭이 울자 바깥채로 나와 부모님께 문안드린 뒤, 종일토록 마음을 가라앉힐 길이 없었다. 그럭저럭 날이 저물어 박씨 방에 들어가니 박씨의 엄숙함이 갈수록 더하였다. 시백이 죄지은 사람처럼 앉아서 부인이 말하기만 기다렸는데 어느덧 날이 새었다. 생각다 못하여 다시 나와 후회할 따름이었다.","sp":[[0,2,"P","이시백"],[38,40,"P","이시백"],[42,44,"P","박씨"],[54,56,"P","박씨"],[86,88,"P","이시백"],[104,106,"P","박씨"],[140,142,"P","이시백"],[155,157,"P","이득춘 부인"],[201,203,"P","박씨"],[240,242,"P","이시백"],[325,327,"P","박씨"],[336,338,"P","박씨"],[355,357,"P","이시백"],[372,374,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"이때 박씨가 이같이 한 지 여러 날이었다. 시백은 절로 병이 들어 먹고 마시는 것이 줄어들었다. 홀로 앉아 생각하기를 '아내라는 것이 흉물이라 평생의 한을 가슴속에 품고 있다가 지금은 미인이 되었으니, 말이라도 통하지 못하면 골수에 병이 될 것이다. 첫째는 사람 볼 줄 몰랐던 탓이요 둘째는 신세가 가련하구나.' 하고, 정신을 가다듬고 마음을 다잡아 다시 들어가 말이라도 통해 보리라 하였다. 피화당에 들어가 거듭 죄를 빌며 말하였다. \"부인 침소에 여러 번 들어왔으나 끝내 마음을 풀지 않으시니 이는 나의 허물이라 누구를 원망하겠소. 부인 때문에 죽을 지경에 이르렀으니 죽기는 서럽지 않으나, 부모님 슬하에서 효도는 고사하고 젊은 나이에 죽으면 막대한 불효요, 또 저승에 들어간들 무슨 면목으로 조상을 뵙겠소.\"","sp":[[3,5,"P","박씨"],[24,26,"P","이시백"],[245,247,"P","이득춘 부인"],[300,302,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"하며 애처롭게 눈물을 흘리니, 박씨가 그 말을 듣고 이미 측은하였다. 그제야 붉은 입술을 반쯤 열어 꾸짖어 말하였다. \"우리 조선은 예의지국입니다. 사람이 오륜을 모르면 예의를 어찌 알겠습니까. 그대는 아내가 박색이라 하여 삼 년을 천대하였으니 부부유별이 어디 있습니까. 옛사람이 이르기를 조강지처(糟糠之妻)는 내쫓지 않는다 하였는데, 아름다운 얼굴만 생각하고 부부의 의리가 귀중한 줄 몰라보니 어찌 장부의 행실이라 하며 덕이 있다 하겠습니까. 이후로는 효도로 부모를 섬기고 충성으로 나라를 도우십시오. 만일 그렇지 않으면 나는 비록 여자이나 그대 같은 장부는 부러워하지 않겠습니다.\"","sp":[[17,19,"P","박씨"]]},{"c":1,"sub":"","t":"하며 말이 바르고 곧으니 시백이 듣고 대답할 말이 없었다. 염치 불고하고 거듭 애걸할 뿐 달리 대답하지 못하니, 박씨가 한참 보다가 측은한 마음이 움직여 그제야 돌아앉으며 공경히 말하였다. \"내가 본래 모습을 감추고 못생기게 한 것은 그대가 미색에 빠지지 않게 하여 한 몸의 정기를 온전하게 하려 함이요, 며칠 말을 붙이지 않은 것은 정성을 보려 함이었습니다. 지금 본래 모습을 되찾았으나 평생 마음을 풀지 말자 하였는데, 여자의 마음이 약하니 이제부터는 지난 일을 버리시고 부디 다시는 사람을 알아보십시오.\"","sp":[[14,16,"P","이시백"],[63,65,"P","박씨"],[159,161,"P","임금"]]},{"c":1,"sub":"","t":"하니 시백이 크게 기뻐하여 말하였다. \"나는 인간 세상의 무식한 사람이요 부인은 신선의 골격이라, 지략이 넓어 보통 사람과 다르므로 만 리 밖을 내다보는데, 나 같은 사람은 용렬한 인물이라 식견이 모자라 착한 부인을 박대하였으니 죄가 죽어도 아깝지 않습니다. 그러나 지혜로운 사람도 천 번 생각에 반드시 한 번 실수가 있다 하였으니, 하물며 나 같은 한낱 필부야 말해 무엇하겠습니까. 부인은 삼 년 맺힌 마음을 풀어 버리시고 평생을 즐겁게 지냅시다.\" 박씨가 웃으며 말하였다. \"누가 옳고 누가 그른지 간에 지난 일은 풀어 버리니 안심하십시오.\"","sp":[[3,5,"P","이시백"],[41,43,"P","이득춘 부인"],[117,119,"P","이득춘 부인"],[215,217,"P","이득춘 부인"],[253,255,"P","박씨"]]},{"c":1,"sub":"","t":"밤이 이미 삼경이었다. 지난 일을 다 풀고 나서 이부자리를 펴고 비취 같은 정과 원앙의 즐거움을 이루니 그 정이 비할 데가 없었다. 그 뒤로부터 상공과 부인과 노복들이 전에 박씨를 천대한 것을 이제야 깨닫고 잘못을 뉘우치며 스스로 꾸짖었다. 박씨의 신묘함과 상공의 지략에 탄복하지 않는 이가 없었고, 온 집안이 위아래 없이 화평하게 지냈다.","sp":[[81,83,"P","이득춘"],[85,87,"P","이득춘 부인"],[89,92,"P","노복들"],[97,99,"P","박씨"],[135,137,"P","박씨"],[144,146,"P","이득춘"]]},{"c":1,"sub":"","t":"한편 이때 박씨가 모습이 바뀌었다는 소식이 장안에 자자하니, 여러 재상가 부인들이 그 신묘한 일을 구경하고자 편지를 보냈다. 그 사연에 이르기를, 때는 마침 봄 석 달이라 날은 따뜻하고 바람은 온화하여 초목과 뭇 생명이 다 새로워졌으니, 이같이 좋은 때에 한번 꽃구경 겸 만나자 하였다. 박씨가 허락하는 답장을 보내고, 그날이 되자 고운 옷으로 단장하고 꽃가마를 타고 계화를 데리고 모이기로 한 곳을 찾아가니 여러 부인들이 모여 있었다. 꽃가마에서 내려 인사를 마치고 자리를 정한 뒤 좌우를 살펴보니, 여러 부인들이 녹의홍상(綠衣紅裳)으로 치레를 화려하게 하였다.","sp":[[6,8,"P","박씨"],[37,44,"P","재상가 부인들"],[161,163,"P","박씨"],[206,208,"P","계화"],[229,234,"P","재상가 부인들"],[281,286,"P","재상가 부인들"]]},{"c":1,"sub":"","t":"여러 부인들이 박씨를 한번 보기를 원하던 차에 바라보니, 옥 같은 얼굴과 구름 같은 귀밑머리는 동정호의 밝은 달 같고 옷차림은 꽃빛도 빛을 잃을 만하였다. 여러 부인의 고운 태도도 박씨에 비하면 오히려 빛을 잃으니 누가 탄복하지 않겠는가. 술과 안주를 내어 서로 권할 때, 박부인이 재주를 보이려고 술잔을 받다가 일부러 술잔을 비단 적삼에 떨어뜨리니 술이 엎질러져 치마가 젖었다. 박부인이 치마를 벗어 계화에게 주며 말하였다. \"불꽃 속에 태워라.\" 하니 계화가 명을 받고 치마를 불 속에 던졌는데, 그 치마는 멀쩡하고 빛이 더욱 윤기가 났다. 계화가 치마를 가져다 박부인께 드리니, 여러 부인이 그 모습을 보고 다 놀라 까닭을 물었다. 박씨가 대답하였다. \"이 비단의 이름은 오화단(五花緞)이라 하는데, 혹 때가 묻으면 물로 빨지 못하고 불에 태워 때를 씻습니다.\"","sp":[[0,5,"P","재상가 부인들"],[8,10,"P","박씨"],[87,92,"P","재상가 부인들"],[101,103,"P","박씨"],[153,156,"P","박씨"],[213,216,"P","박씨"],[225,227,"P","계화"],[255,257,"P","계화"],[305,307,"P","계화"],[317,320,"P","박씨"],[327,332,"P","재상가 부인들"],[357,359,"P","박씨"]]},{"c":1,"sub":"","t":"여러 부인이 이 같은 신묘함을 보고 거듭 탄복하며 또 물었다. \"그 비단은 어디에서 났습니까?\" 박부인이 대답하였다. \"인간 세상에는 없고 달나라에서 난 것입니다.\" 모든 부인이 또 물었다. \"입으신 저고리는 무슨 비단입니까?\" 박씨가 대답하였다. \"이 비단의 이름은 명월단(明月緞)인데, 제 친정아버지께서 동해 용궁에 가셨을 때 얻어 오신 것이니 용궁에서 난 것입니다. 이 비단은 물에 넣어도 젖지 않고 불에 넣어도 타지 않습니다.\" 하거늘 여러 부인들이 듣고 신기하게 여겨 칭찬하지 않는 이가 없었다. 저마다 시비를 시켜 박부인에게 술을 권하기를 그치지 않으니, 박부인이 술잔을 받아 들고 금봉채(金鳳釵)를 빼어 술잔 가운데를 긋고 마시니, 술이 한쪽은 없어지고 한쪽은 칼로 벤 듯 남아 있었다. 여러 부인이 그 술을 보고 더욱 신기하여 칭찬하였다.","sp":[[0,5,"P","재상가 부인들"],[54,57,"P","박씨"],[96,98,"P","이득춘 부인"],[128,130,"P","박씨"],[248,253,"P","재상가 부인들"],[294,297,"P","박씨"],[317,320,"P","박씨"],[392,397,"P","재상가 부인들"]]},{"c":1,"sub":"","t":"\"부인은 선관의 딸이라 하더니 과연 그 말이 옳구나. 진시황과 한무제도 구하지 못한 신선을 우리가 오늘 만났으니 이 아니 신기하고 즐겁겠는가.\" 서로 봄 흥취를 이기지 못하여 글을 지어 화답하는데, 이때 계화가 곁에 있다가 여쭈었다. \"이렇게 좋은 봄 경치에 흥겹게 놀지도 못하는데 온갖 꽃이 만발하여 봄빛을 자랑하니, 저도 이때를 맞아 맑은 노래 한 곡조로 여러 부인을 위로할까 합니다.\" 모든 부인이 그 말을 듣고 더욱 기특하게 여겨 그리하라 하니, 계화가 붉은 입술을 반쯤 열어 맑은 노래 한 곡조를 부르는데, 그 소리가 매우 맑고 애처로워 산호 채로 옥 쟁반을 깨뜨리는 듯하였다. 그 노래에 이르기를, 천지는 만물이 쉬어 가는 여관이요 세월은 백대를 지나가는 나그네라.","sp":[[1,3,"P","이득춘 부인"],[5,7,"P","박처사"],[114,116,"P","계화"],[201,206,"P","재상가 부인들"],[222,224,"P","이득춘 부인"],[254,256,"P","계화"]]},{"c":1,"sub":"","t":"하루살이 같은 세상에 늙어 가니[?], 봄바람에 가는 버들 좋은 때에 아니 놀고 어이하리. 옛일을 생각하고 지금 세상을 살펴보니 백대홍안(白黛紅顏)[?]은 봄바람에 흐드러졌구나. 한때의 번화함은 장주(莊周)의 나비[?]로다. 푸른 산 두견화는 촉나라 원혼이요, 화단의 봄새 소리는 왕소군(王昭君)의 눈물이라. 세상을 생각하니 이 세상이 뜻이 없도다. 구십 일 봄빛 좋은 때에 아니 놀고 무엇 하리. 어화 세상 사람들아. 푸른 바다로 술을 빚어 만세토록 홀로 즐겨 보자 하였다. 모든 부인이 다 듣고 나자 정신이 맑아져 계화를 돌아보며 무수히 칭찬하였다. 이윽고[?] 석양은 서산에 걸리고 사람 그림자는 어지러운데, 산새는 펄펄 날아들고 달은 동쪽 고개에 떠오르니, 계화가 잔치를 마치는 곡조를 타자 여러 부인이 잔치를 끝내고 각각 돌아갔다.","sp":[[270,272,"P","이득춘 부인"],[290,292,"P","계화"],[372,374,"P","계화"],[391,396,"P","재상가 부인들"]]},{"c":1,"sub":"","t":"한편 상공이 나이가 많아 벼슬을 내놓으니, 임금께서 시백의 품계를 올려 부르셨다. 시백이 입궐한 뒤 나라를 충성으로 섬겨 명망이 조정에 떨치니, 임금께서 더욱 아끼시어 시백을 평안감사에 임명하셨다. 시백이 임금의 은혜에 감사하고 대궐에 들어가 숙배하고 하직한 뒤 본가로 돌아와 부모께 뵈니, 상공이 임금의 은혜를 거듭 칭송하였다. 시백이 급히 행장을 차리면서 장인(匠人)을 불러 쌍교(雙轎)를 꾸미라 하니 박씨가 물었다. \"쌍교는 무엇 하려 하십니까?\"","sp":[[3,5,"P","이득춘"],[24,26,"P","임금"],[29,31,"P","이시백"],[46,48,"P","이시백"],[81,83,"P","임금"],[94,96,"P","이시백"],[100,102,"P","이시백"],[111,113,"P","이시백"],[115,117,"P","임금"],[123,125,"P","이시백"],[163,165,"P","이득춘"],[167,169,"P","임금"],[185,187,"P","이시백"],[227,229,"P","박씨"]]},{"c":1,"sub":"","t":"감사가 대답하였다. \"나 같은 사람을 평안감사에 임명하셨으니 임금의 은혜가 망극합니다. 이번 길에 부인을 데려가고자 합니다.\" 부인이 크게 놀라 말하였다. \"대장부가 세상에 나서면 나라 섬길 날은 많고 부모 섬길 날은 적다 하였으니, 나랏일에 골몰하면 아녀자를 돌아보지 못합니다. 제가 함께 가면 부모님은 누가 봉양하겠습니까. 저는 집에 있으면서 부모님을 봉양할 것이니 당신은 충성을 다하여 이름을 빛내십시오.\" 감사가 이 말을 들으니 이치가 당연하고 말이 바르고 곧았다. 도리어 탄복하여 말하였다. \"나 같은 사람은 불효하고 불충함이 이러하니 하늘과 땅 사이에 용납되지 못할 사람입니다. 늙으신 부모님을 생각하지 못하고 망령되이 말하였으니 허물로 여기지 마시고, 부모님을 극진히 봉양하여 남의 웃음을 면하게 해 주십시오.\"","sp":[[0,2,"P","이시백"],[23,25,"P","이시백"],[34,36,"P","임금"],[55,57,"P","이득춘 부인"],[71,73,"P","이득춘 부인"],[231,233,"P","이시백"]]},{"c":1,"sub":"","t":"하고 사당에 들어가 절하여 하직하고 부모께 하직한 뒤 길을 떠나는데, 박씨와 은근히 작별하고 떠났다. 감사가 여러 날 만에 감영에 이르니, 각 고을 수령들의 폐단이 무수하여 양민이 도탄에 빠지고 민심이 곳곳에서 소란하였다. 감사가 부임한 뒤 그 폐단을 하나하나 염탐하여, 잘 다스리지 못한 수령은 곤장을 쳐서 파면하고 잘 다스린 수령은 칭찬하여 드러내며 백성을 인의로 다스렸다. 한 해 사이에 도내 여러 고을이 잘 다스려지니 백성들이 거리마다 노래하였다.","sp":[[39,41,"P","박씨"],[57,59,"P","이시백"],[125,127,"P","이시백"]]},{"c":1,"sub":"","t":"\"좋을시고, 이제는 살겠구나. 요순(堯舜) 시절인가. 나라가 태평하고 백성이 편안하니 좋을시고. 신농씨(神農氏)가 내신 따비를 이제야 써 보세. 역산(歷山)의 밭을 갈아 농사를 지어 보세. 부모 형제 한데 모여 배불리 먹고 배를 두드려 보세. 얼널널 상사뒤요. 구관 사또께서 어찌하여 평민을 다스릴[?] 적에는 무식한 백성들이 인의예지를 어찌 알며 효제충신을 어찌 알겠는가. 불효와 불제(不悌)를 일삼아 골육끼리 서로 다투니 천지간이 어지러울 적에 효자가 불효자 되고 양민이 도적 되어 죽기만 바랐더니, 신관 사또 부임한 뒤에 충과 효를 함께 갖추어 인의로 공무를 보시고 덕화가 사방에 퍼졌으니 백성들아 살아 보세. 불효한 놈이 효자 되고 도적이 양민 되어 산에는 도적이 없고 길에 떨어진 물건도 줍지 않을 적에 부지런히 농사지어 재물 모아 부귀하게 되어 보세. 얼널널 상사뒤야. 선정비를 세워 보세. 얼널널 상사뒤야. 우리 사또 착하실시고. 비석을 세워 덕을 기려 보세.\"","sp":[]},{"c":1,"sub":"","t":"거리마다 선정비를 세워 놓고 격양가(擊壤歌)를 일삼았다. 이럭저럭 감사의 어진 소문이 멀고 가까운 곳에 자자하고 조정에까지 미치니, 임금께서 들으시고 칭찬을 마지않으시며 품계를 다시 올려 병조판서로 부르셨다. 감사가 교지를 받들어 북쪽을 향해 절하고 임금의 은혜에 감사한 뒤 즉시 행장을 차려 서울로 올라가니, 여러 고을 수령과 사방 백성들이 무수히 칭송하였다. 여러 날 만에 서울에 이르러 대궐에 들어가 사은하니 임금께서 입이 마르도록 크게 칭찬하셨다. 그날로 본가에 돌아와 사당에 뵈온 뒤 부모님께 문안드리고, 며칠 지난 뒤에 멀고 가까운 친척을 모아 잔치를 베풀고 서로 즐거워하였다.","sp":[[37,39,"P","이시백"],[74,76,"P","임금"],[105,109,"P","이시백"],[117,119,"P","이시백"],[140,142,"P","임금"],[148,150,"P","이시백"],[232,234,"P","임금"]]},{"c":1,"sub":"","t":"한편 이때는 갑자년 가을 팔월이었다. 남경(南京)이 어지럽다 하자 임금께서 시백을 장수로 임명하셨다. 시백이 어명을 받고 남경으로 들어가는데, 이때 임경업(林慶業)이 총명하고 영리하여 변화의 술법을 지녔는데 마침 철마산 중군(中軍)에 임명되어 있었다. 시백이 임금께 아뢰어 경업을 장사군관(壯士軍官)으로 삼아 함께 남경에 들어가니, 천자가 조선 사신이 온다는 말을 듣고 원접사(遠接使)를 보내어 맞아들였다. 이때 북방 호국(胡國)이 총마 가달의 난을 만나 망할 지경에 이르러 중국에 구원병을 청하였는데, 상장(上將)을 얻지 못하고 있었다. 원접사 황재명이 아뢰었다.","sp":[[37,39,"P","임금"],[42,44,"P","이시백"],[57,59,"P","이시백"],[83,86,"P","임경업"],[141,143,"P","이시백"],[145,147,"P","임금"],[153,155,"P","임경업"],[186,188,"P","남경 천자"],[207,210,"P","황재명"],[242,247,"P","총마 가달"],[302,305,"P","황재명"],[306,309,"P","황재명"]]},{"c":1,"sub":"","t":"\"조선 사신의 군관을 보니 비록 작은 나라의 인물이나 만고의 흥망과 천지의 조화를 품었으니 어찌 기특하지 않겠습니까. 원컨대 이 사람을 구원병의 장수로 정하는 것이 마땅할까 합니다.\" 천자가 들으시고 즉시 시백과 경업을 불러 보시고 칭찬하시며, 경업을 구원병 대장으로 삼아 호국을 구하라 하셨다. 경업이 명을 받고 즉시 호국에 들어가 총마 가달을 한 번 싸움에 물리치고 승전고를 울리며 중국으로 돌아와 황제께 뵈었다. 황제가 크게 칭찬하시어 상을 후하게 내리시고 글월을 주어 조선으로 보냈다.","sp":[[103,105,"P","남경 천자"],[115,117,"P","이시백"],[119,121,"P","임경업"],[137,139,"P","임경업"],[166,168,"P","임경업"],[187,192,"P","총마 가달"],[225,227,"P","남경 천자"],[234,236,"P","남경 천자"]]},{"c":1,"sub":"","t":"시백과 경업이 황제께 하직하고 밤낮으로 길을 재촉하여 조선에 이르러 대궐에 들어가니, 임금께서 보시고 칭찬하셨다. \"작은 나라의 인물로 큰 나라의 도원수가 되어 호국을 구하고 가달국까지 위엄을 떨쳤으니 만고에 없는 일이다.\" 두 사람의 벼슬을 올려 시백을 우의정에, 경업을 부원수에 임명하셨다. 그런데 이때 호국이 강성해져 도리어 조선을 엿보았다. 임금께서 크게 근심하시어 부원수 임경업을 의주부윤에 임명하여 자주 침노하는 북쪽 적을 쳐서 물리치라 하셨다. 임경업이 하직하고 숙배한 뒤 의주에 부임하여 밤낮으로 군사를 조련하니, 오랑캐가 남쪽을 두려워하여 자주 침범하지 못하였다.","sp":[[0,2,"P","이시백"],[4,6,"P","임경업"],[8,10,"P","남경 천자"],[48,50,"P","임금"],[98,100,"P","총마 가달"],[139,141,"P","이시백"],[143,146,"P","이시백"],[149,151,"P","임경업"],[153,156,"P","임경업"],[195,197,"P","임금"],[209,212,"P","임경업"],[213,216,"P","임경업"],[218,222,"P","임경업"],[256,259,"P","임경업"]]},{"c":1,"sub":"","t":"한편 흥이 다하면 슬픔이 오는 것은 사람에게 늘 있는 일이다. 대감의 나이가 이제 여든이었다. 갑자기 병이 들어 온갖 약이 효험이 없고 점점 위중해지자, 시백과 박씨를 불러 앉히고 거듭 슬퍼하시다가 세상을 떠나셨다. 백 일 안에 부모님이 모두 돌아가시니 어찌 망극하지 않겠는가. 초상의 모든 절차를 예법대로 치르고 애통함을 그치지 않았다. 한편 오랑캐가 강성하여 자주 침범하니, 경업이 백 번 싸워 백 번 이겨 물리치고 북방을 굳게 지켰다. 호왕이 여러 신하를 모아 말하였다. \"우리나라 땅이 넓으나 조선의 임경업을 누를 신하가 하나도 없으니 어찌 가련하지 않은가.\"","sp":[[35,37,"P","이득춘"],[86,88,"P","이시백"],[90,92,"P","박씨"],[212,214,"P","임경업"],[247,249,"P","호왕"],[284,287,"P","임경업"]]},{"c":1,"sub":"","t":"하니 신하들이 아무 대답도 하지 못하였다. 이때 호왕의 왕비는 비록 여자이나 만고에 없는 영웅이었다. 위로는 천문에 통하고 아래로는 지리를 살펴, 앉아서 천 리 밖의 일을 알고 서서 만 리 밖의 일을 알았다. 그래서 왕비가 호왕께 아뢰었다. \"제가 요사이 천기를 살펴보니 조선에 신인(神人)이 있는 듯합니다. 만일 신인이 있다면 설사 경업을 누른다 해도 조선을 도모하기 어려울 듯합니다.\" 호왕이 크게 놀라 말하였다. \"내 평생 경업을 두려워하기를 팔 년 풍진에 산을 뽑던 초패왕(楚霸王)과 삼국 시절의 조자룡(趙子龍)보다 더 두려워하였는데, 또 그 위로 뛰어난 신인이 있다면 어찌 다시 엿볼 뜻을 두겠소.\"","sp":[[27,29,"P","호왕"],[31,33,"P","호국 왕비"],[121,123,"P","호국 왕비"],[125,127,"P","호왕"],[187,189,"P","임경업"],[218,220,"P","호왕"],[240,242,"P","임경업"]]},{"c":1,"sub":"","t":"스스로 탄식하기를 그치지 않으니 왕비가 다시 아뢰었다. \"이제 천기를 보니 조선의 운수가 다하였습니다. 그러나 백만 대병을 보내도 그 신인을 없애기 전에는 조선을 도모하기 어려우니, 제가 한 가지 묘한 계책을 생각하였습니다. 자객을 구하여 먼저 조선에 보내 그 신인을 없앤 뒤에 조선을 도모하는 것만 못합니다.\" 호왕이 말하였다. \"그러면 어떤 사람을 보내고자 하오?\" 왕비가 대답하였다. \"조선 사람은 재물을 탐하고 여색을 좋아하니, 이제 계집을 구하되 인물은 가을 달 같고, 문장은 이백(李白)이요, 필법은 왕희지(王羲之)요, 말솜씨는 육국 합종연횡 시절의 소진(蘇秦)과 장의(張儀)를 겸하고, 칼 쓰기는 조자룡과 관운장(關雲長)을 비웃으며, 도량은 제갈공명 같은 계집을 보내면 일을 이룰 듯합니다.\"","sp":[[18,20,"P","호국 왕비"],[175,177,"P","호왕"],[207,209,"P","호국 왕비"]]},{"c":1,"sub":"","t":"하니 호왕이 듣고 말하였다. \"그 꾀가 매우 기묘하다.\" 하고 즉시 신하들과 의논하여 사방으로 구하였다. 마침 여러 나라 신녀(神女)[?] 가운데 길홍대라 하는 계집이 있었는데, 인물은 당 명황(唐明皇)의 양귀비 같고, 말솜씨는 소진과 장의를 비웃으며, 검술은 염파(廉頗)와 이목(李牧)을 비웃고, 용맹은 용과 범 같았다. 왕비가 호왕을 보고 아뢰었다. \"길홍대는 검술과 도량과 문필이 뛰어나고 게다가 인물이 절색이요, 또 만 명도 당하지 못할 용맹을 지녔으니 이 사람을 보내면 일을 이룰 듯합니다.\" 하니 호왕이 크게 기뻐하여 길홍대를 불러 보고 말하였다. \"네가 나가서 조선을 엿보고 큰 공을 이루어 이름을 세우라.\"","sp":[[3,5,"P","호왕"],[82,85,"P","길홍대"],[181,183,"P","호국 왕비"],[185,187,"P","호왕"],[199,202,"P","길홍대"],[284,286,"P","호왕"],[296,299,"P","길홍대"]]},{"c":1,"sub":"","t":"하니 길홍대가 아뢰었다. \"소녀가 재주는 없으나 나라의 은혜가 망극하니 어찌 물불인들 피하겠습니까.\" 호왕이 말하였다. \"네 말이 매우 기특하구나. 조선에 나가 신인의 머리를 베어 온다면 천금의 상을 주고 만호후(萬戶侯)에 봉할 것이요, 이름을 역사에 올려 만세에 전하게 하리라.\" 길홍대가 아뢰었다. \"소녀가 재주는 없으나 한번 조선에 나가 영웅과 요술 부리는 사람을 한칼에 베어 대왕의 근심을 덜겠습니다.\" 왕이 백 번 당부하였다. \"조선에 나가면 말이 다를 것이니 자세히 알고 가라.\"","sp":[[3,6,"P","길홍대"],[57,59,"P","호왕"],[148,150,"P","임금"],[158,161,"P","길홍대"]]},{"c":1,"sub":"","t":"조선말과 조선 풍속을 가르친 뒤에 다시 일렀다. \"조선에 나가거든 먼저 장안에 들어가 우의정 집을 찾아가면 신인이 있을 것이니, 묻고 답하기는 이러이러하게 하고 부디 재주를 보이지 말아라. 신인을 꾀어 머리를 베어 가지고 오는 길에 의주에 들어가 임경업을 베어 가지고 돌아오되, 부디 조심하여 큰일을 그르치지 마라.\" 하니 길홍대가 하직하고 나와 행장을 차려 곧장 동쪽을 향하여 장안에 이르렀다. 한편 이때 박씨 부인이 천문을 살펴보고 우의정을 청하여 말하였다. \"아무 달 아무 날에 어떤 여자가 문 앞에 와서 문안하고 주고받는 말이 황홀할 것이니, 부디 조심하여 가까이 대접하지 말고 피화당으로 인도하여 보내십시오.\"","sp":[[48,51,"P","이시백"],[138,141,"P","임경업"],[181,184,"P","길홍대"],[228,233,"P","박씨"],[244,247,"P","이시백"]]},{"c":1,"sub":"","t":"우의정이 대답하였다. \"어떤 여자이기에 나를 찾아온단 말이오?\" 부인이 말하였다. \"그것은 나중에 아실 것이니 함부로 말을 퍼뜨리지 마시고 제 말대로 하여 낭패를 보지 마십시오. 그 계집이 오면 사랑에서 묵기를 청할 것이니 부디 조심하여 그 간계에 속지 마십시오. 그 여인은 얼굴이 기묘하고 온갖 태도를 갖추었을 뿐 아니라 문필이 넉넉하니, 그 기묘한 것을 사랑하여 만일 동침하다가는 큰 화를 당할 것입니다. 부디 그 간계에 속지 말고 피화당으로 보내십시오. 그사이에 술을 빚게 하되, 한 그릇은 쌀 두 말에 열씨[?] 서 되를 섞어 빚고 또 한 그릇은 순한 술로 빚어 두고 안주를 많이 준비하였다가, 그날이 되거든 제 말대로 이러이러하게 하십시오.\"","sp":[[0,3,"P","이시백"],[36,38,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"우의정이 듣고 한편으로 이상히 여기면서도 허락하고 술과 안주를 많이 장만하였다. 이때 길홍대가 헤아릴 수 없는 마음을 품고 조선에 이르러 승상 댁을 찾았다. 그날이 되자 과연 여자가 치레를 화려하게 하고 승상께 문안하니 승상이 물었다. \"너는 어떤 여인이냐?\" 길홍대가 대답하였다. \"소녀는 시골에 사는 기생인데 장안 구경을 왔다가 노자도 모자라고 머물 곳이 마땅치 않아 두루 헤매다가 외람되이 대감 댁 문 앞에 이르렀습니다.\" 승상이 말하였다. \"그러면 본래 어디에 살며 성명은 무엇이라 하느냐?\"","sp":[[0,3,"P","이시백"],[48,51,"P","길홍대"],[77,79,"P","이시백"],[114,116,"P","이시백"],[123,125,"P","이시백"],[146,149,"P","길홍대"],[221,223,"P","이득춘"],[240,242,"P","이시백"]]},{"c":1,"sub":"","t":"길홍대가 공경히 대답하였다. \"소녀는 강원도 회양에 사는데, 일찍 부모를 여의고 떠돌며 빌어먹다가 그 고을 관비로 소속되었고, 이름은 설중매(雪中梅)라 합니다.\" 말이 부드럽고 태도가 비범하였다. 승상이 그 모습을 살펴보니 여느 계집과 달랐으므로 속으로 의심하며 자리를 주어 앉힌 뒤, 한참을 아끼며 이야기를 무르익게 나누었다. 문필이 넉넉하고 말하는 모습은 푸른 산에 흐르는 물 같고 도량은 넓은 바다 같아 묻고 답하는 것이 능란하였다. 승상이 크게 칭찬하기를 '장안에도 문장가와 재사가 허다하나 이에 미치지 못하겠다.' 하며 몹시 아꼈으나, 박씨가 하던 말을 생각하니 의심이 많았다. 다시 일렀다. \"지금 석양이 서산에 걸리고 날이 저물었으니 후원 피화당으로 들어가 편히 쉬어라.\" 하시니 그 여인이 대답하였다.","sp":[[0,3,"P","길홍대"],[75,78,"P","길홍대"],[110,112,"P","이시백"],[246,248,"P","이시백"],[305,307,"P","박씨"]]},{"c":1,"sub":"","t":"\"소인은 먼 지방의 천한 기생으로 외람되이 대감 앞에 나섰으니, 오늘 밤 대감을 모시고 아득한 마음을 분명히 깨우칠까 합니다.\" 승상이 말하였다. \"나도 너와 함께 지낼 마음이 간절하나 오늘 밤 숙직할 일[?]이 있어 너와 동침하지 못하니 뒷날을 기약하자. 섭섭하게 생각하지 말고 안채에 들어가 편히 쉬어라.\" 하니 그 여인이 대답하였다. \"소녀같이 미천한 몸이 꿈엔들 어찌 존귀한 부인을 모시고 하룻밤이라도 지내겠습니까. 지극히 옳지 않습니다.\"","sp":[[24,26,"P","이득춘"],[41,43,"P","이득춘"],[72,74,"P","이시백"],[214,216,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"승상이 말하였다. \"네 말이 사세로 보아 당연하나, 부인과 너는 둘 다 여인이니 무슨 허물이 있겠느냐.\" 하시며 즉시 시녀 계화를 불러 분부하였다. \"이 여인을 데려다가 피화당에서 편히 쉬게 하라.\" 하시니 계화가 명을 받고 즉시 그 여인을 인도하여 피화당으로 들어가 박씨께 대감이 분부하신 말씀을 여쭈었다. 박씨가 듣고 그 여인을 청하니, 그 여인이 들어와 서로 인사를 마치고 자리를 정하였다. 박씨가 물었다. \"그대는 어떤 사람이기에 내 집을 찾아왔느냐?\"","sp":[[0,2,"P","이시백"],[29,31,"P","이득춘 부인"],[66,71,"P","계화"],[116,118,"P","계화"],[150,152,"P","박씨"],[154,156,"P","이득춘"],[173,175,"P","박씨"],[222,224,"P","박씨"]]},{"c":1,"sub":"","t":"그 여인이 말하였다. \"소녀는 먼 지방의 천한 기생인데 서울에 구경 왔다가 길을 잃고 외람되이 댁을 찾아왔으니 황공하기 그지없습니다.\" 박씨가 말하였다. \"그대의 모습을 보니 보통 사람과 다르구나. 헛되이 먼 길에 힘만 들이고 부질없이 찾아왔도다.\" 하고 계화를 불러 \"지금 손님이 오셨으니 술과 안주를 들여라.\" 하니 계화가 명을 받고 옥쟁반에 좋은 음식을 갖추고, 술은 두 그릇을 가져다 문밖에 감추어 두었다. 계화에게 술을 권하게 하는데, 독한 술은 그 여인에게 돌리고 순한 술은 박씨에게 돌렸다. 그 여인은 먼 길에 지쳐 주림과 목마름이 심하던 터라 조금도 사양하지 않고 한 말 술을 두어 순배에 다 마시니 그 모습이 보통 사람과 달랐다. 박씨 또한 마시는 법이 조금도 취기가 없었다. 이때 승상과 집안사람들이 그 모습을 보고 이상히 여겨 뒷문 밖에 몸을 숨기고 한참 지켜보다가 여러 사람이 다 놀랐다. 이때 길홍대가 독한 술을 잔뜩 마셔 크게 취하자 박씨께 청하였다.","sp":[[76,78,"P","박씨"],[143,145,"P","계화"],[179,181,"P","계화"],[232,234,"P","계화"],[272,274,"P","박씨"],[362,364,"P","박씨"],[391,393,"P","이시백"],[457,460,"P","길홍대"],[481,483,"P","박씨"]]},{"c":1,"sub":"","t":"\"소녀가 먼 길에 지친 데다 주신 술을 많이 마셔 크게 취하였으니 잠깐 눕기를 청합니다.\" 박씨가 대답하였다. \"술로 손님을 대접하는 것은 예의의 떳떳한 일이요 인륜의 공통된 도리이니, 어찌 내 집에 오신 손님을 공경하지 않겠느냐.\" 그 여인이 말하였다. \"이같이 정성스럽게 대해 주시니 황공하고 감사합니다.\" 하며 이야기가 무르익었는데, 서로 차이가 없었다. 그 여인이 생각하기를 '우리 왕비께 하직할 때 조선에 나가 우의정 집을 찾아가면 자연히 알 일이 있으리라 하시더니, 과연 승상의 상을 보니 다만 어진 재상일 뿐 다른 조화는 없어 보이기에 염려 없다 여겼는데, 부인의 상을 보니 비록 여자이나 미간에 천지의 조화를 은근히 품었으니 이 사람이 곧 신인이로다. 만일 이 사람을 살려 두면 우리 왕께서 조선을 도모하기 어려울 것이니 어찌 근심이 되지 않겠는가. 내가 좋은 묘책을 내어 이 사람을 죽여서 왕의 근심을 덜고 내 이름을 천추에 전하리라.' 하며 속으로 크게 기뻐하였다. 그러나 좋은 일에는 마가 끼는 법이라, 술이 크게 취하여 박씨께 청하였다.","sp":[[51,53,"P","박씨"],[166,168,"P","이시백"],[218,220,"P","호국 왕비"],[235,238,"P","이시백"],[270,272,"P","이시백"],[319,321,"P","이득춘 부인"],[471,473,"P","임금"],[527,529,"P","박씨"]]},{"c":1,"sub":"","t":"\"황공하오나 자기를 청합니다.\" 박씨가 허락하고 베개를 주며 말하였다. \"먼 길에 지쳤을 것이니 자거라.\" 하니 길홍대가 베개를 베고 누워 잠이 들었는데, 두 눈은 화등잔 같고 불덩이가 내달아 방 안에 구르며, 자는 숨결에 방문이 열렸다 닫혔다 하여 사람의 정신을 어지럽게 하였다. 비록 여자이나 범 같은 장사이니 어찌 놀랍지 않겠는가. 박씨도 자는 체하다가 일어나 그 여인의 행장을 열어 보니 칼이 있었는데 주홍빛으로 '비연도(飛燕刀)'라 새겨져 있었다. 박씨가 그 칼을 만지려 하니 그 칼이 변하여 나는 제비가 되어 천장으로 솟구치며 박씨를 향해 해치려 하였다. 박씨가 급히 진언을 외며 술법을 걸어 막으니 그 칼이 감히 범하지 못하고 변화도 부리지 못하였다. 그제야 그 칼을 들고 벼락같이 소리를 지르며 길홍대를 깨우니, 길홍대가 한창 깊이 잠들었다가 벼락 같은 소리에 잠을 깨어 정신이 흐릿한 채 일어나 앉았다. 박씨가 비연도를 비껴들고 꾸짖었다.","sp":[[18,20,"P","박씨"],[63,66,"P","길홍대"],[189,191,"P","박씨"],[256,258,"P","박씨"],[301,303,"P","박씨"],[317,319,"P","박씨"],[397,400,"P","길홍대"],[407,410,"P","길홍대"],[459,461,"P","박씨"]]},{"c":1,"sub":"","t":"\"무지하고 개 같은 년아, 네가 호국의 요물 길홍대가 아니냐.\" 하는 소리가 천지가 무너지는 듯하니, 그 여인이 넋이 빠지고 혼이 나가 어찌할 줄 모르다가 겨우 정신을 차려 고개를 들어 보았다. 박씨가 칼을 들고 있는 위엄은, 팔 년 풍진 홍문연(鴻門宴) 잔치에서 번쾌(樊噲)가 항장(項莊)을 마주하여 머리털이 곤두서고 눈초리가 찢어지며 살기가 하늘을 찌르는 듯하였다. 길홍대가 바로 보지 못하고 말도 못한 채 앉아 있다가 마음을 가라앉히고 여쭈었다. \"부인께서 어찌 이같이 아십니까. 과연 길홍대입니다. 황공하기 그지없으나 무슨 까닭으로 이같이 엄하게 물으십니까?\"","sp":[[25,28,"P","길홍대"],[109,111,"P","박씨"],[207,210,"P","길홍대"],[254,256,"P","이득춘 부인"],[275,278,"P","길홍대"]]},{"c":1,"sub":"","t":"부인이 눈을 부릅뜨고 큰 소리로 꾸짖었다. \"너는 한낱 자객으로 개 같은 너의 왕의 말을 듣고 당당한 우리 예의지국을 해치려 하니 어찌 살기를 바라겠느냐. 나는 여자이나 조그마한 네 간계에 어찌 속겠느냐.\" 하며 노기가 등등하여 곧장 비연도로 길홍대의 머리를 겨누며 우레 같은 소리를 벼락같이 지르고 꾸짖었다.","sp":[[0,2,"P","이득춘 부인"],[136,139,"P","길홍대"]]},{"c":1,"sub":"","t":"\"개 같은 오랑캐 년아, 내 말을 들어 보아라. 우리 대감께서 왕명을 받들어 우리나라 장수 임경업을 데리고 남경 사신으로 들어가셨을 때, 너의 나라에서 총마 가달의 난을 만나 망할 지경에 이르러 기운이 다하여 중국에까지 구원병을 청하였다. 남경 천자께서 너의 나라가 버티지 못할 줄 아시고 불쌍히 여기시어 우리나라 장수 임경업을 구원병 장수로 삼아 너의 나라를 구하여 사직을 보전하게 하셨으니, 그 은혜를 갚자 하면 태산도 가벼울 것이다. 그런데 도리어 엿보니 이는 배은망덕이요, 또 너 같은 요물을 보내 우리나라를 탐지하고자 내게 먼저 와서 나를 해치려 하고 내 재주를 시험하려 하니 이는 모두 너의 나라 왕비의 간계다. 나는 너보다 먼저 알았으니 앞뒤 일을 생각하면 너를 죽여도 죄가 남는다. 우선 네 머리를 베어 내 한때의 분을 만분의 일이라도 씻으리라.\" 하니 길홍대가 황망한 가운데 생각하기를 '이런 영웅을 만났으니 성공은커녕 화를 만나 목숨을 보전하지 못하겠구나.' 하였다.","sp":[[30,32,"P","이득춘"],[51,54,"P","임경업"],[85,90,"P","총마 가달"],[134,139,"P","남경 천자"],[179,182,"P","임경업"],[211,213,"P","임금"],[340,342,"P","호국 왕비"],[430,433,"P","길홍대"],[479,481,"P","임금"]]},{"c":1,"sub":"","t":"하고 다시 애걸하였다. \"지극히 황공하오나 부인 앞에서 소녀가 어찌 한마디인들 속이겠습니까. 하찮은 잡술을 배운 잘못으로 제 나라 왕의 명을 거역하지 못하여 이 지경으로 죄를 지었으니 죽어도 아깝지 않습니다. 요망한 소녀가 하늘의 때를 모르고 나왔다가 부인 같은 영웅을 먼저 만났으니 소녀에게는 불행 중 다행입니다. 바라건대 남은 목숨을 살려 고국에 돌아가게 해 주십시오. 소녀가 제 나라 왕에게 이 말을 전하여 다시는 꿈에서라도 어찌 외람된 마음을 먹게 하겠습니까. 소녀가 분수 넘친 죄를 지었으나 이 지경이 된 것은 소녀의 죄가 아니요 왕명을 거역하지 못한 죄이니 부인께서는 깊이 생각해 주십시오. 오늘 남은 목숨을 살려 주시면 부인의 하늘 같은 은덕을 입고 고국에 돌아가 다시 어진 마음을 먹고 무도한 왕의 마음을 고치게 할 것이니 깊이 생각해 주십시오.\"","sp":[[24,26,"P","이득춘 부인"],[141,143,"P","이득춘 부인"],[227,229,"P","임금"],[318,320,"P","이득춘 부인"],[354,356,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"박씨가 말하였다. \"너의 왕은 짐승과 같구나. 은덕을 배반하고 조선을 업신여겨 해치고자 하니 이는 반드시 범을 길러 근심을 남기는 격이다. 어찌 분하지 않겠느냐. 내 뜻은 너 같은 인생을 해칠 마음이 아니나, 그렇다고 어찌 살기를 바라겠느냐.\" 하시니 길홍대가 머리를 숙이고 사죄하였다. \"넓으신 말씀을 들으니 감격하기 그지없습니다.\" 하며 무수히 애걸하니, 부인이 칼을 잠깐 거두고 분한 마음을 가라앉히며 말하였다.","sp":[[0,2,"P","박씨"],[141,144,"P","길홍대"],[201,203,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"\"나의 통분함은 네 왕의 소행을 생각하면 너를 먼저 베어 분한 마음을 대강이라도 풀고자 하나, 사람의 목숨을 죽이는 것은 예사로운 일이 아니다. 또 네 왕은 본래 무도하여 이 같은 뜻을 고치지 않을 듯하기에 너 같은 목숨을 아직 살려 보내니, 돌아가 네 왕에게 내가 하던 말을 자세히 전하여라. 우리 조선은 비록 작은 나라이나 인재를 헤아리면 영웅과 명장이 산처럼 쌓였고, 나 같은 둔한 재주는 수레에 싣고 말로 될 만큼 흔하다. 네 왕비의 말을 듣고 너를 인재로 뽑아 보냈으나, 너 같은 요물이 우리 조선에 나와 영웅을 만나기 전에 나 같은 사람을 만났기에 살아서 돌아가는 것이다. 돌아가서 네 왕에게 이 말을 전하여 이후로는 하늘의 명을 따르게 하라. 만일 교만한 놈이 끝내 거역하면 나는 비록 여자이나 영웅호걸을 모아 군사를 거느리고 네 나라에 들어가 죄가 있든 없든 씨도 없이 없애 버릴 것이니, 부디 하늘의 명을 거역하지 말고 따르게 하라.\" 하고 또 말하였다. \"이 모두가 네 왕비의 허물이 아니라 우리나라 국운이 불행하여 이 지경을 당하였으니 누구를 원망하고 누구를 탓하겠느냐.\"","sp":[[159,161,"P","임금"],[243,245,"P","호국 왕비"],[343,345,"P","임금"],[497,499,"P","호국 왕비"]]},{"c":1,"sub":"","t":"하시며 하늘을 우러러 탄식하였다. 길홍대가 일어나 절하며 사례하였다. \"신명하신 덕택으로 죽을 목숨이 살았으니 감격하기 그지없습니다.\" 부끄러움을 머금고 속으로 생각하기를 '큰일을 꾀하고 만 리를 지척으로 여겨 나왔다가 성공은커녕 본래 일이 탄로 났으니 이제는 어찌 일을 이루기를 바라겠는가. 그저 돌아가는 것만 못하다.' 하고 즉시 본국으로 돌아갔다. 한편 승상과 집안사람들이 그 모습을 보고 크게 두렵게 여겼다. 하루는 승상이 대궐에 들어가 그 사연을 낱낱이 아뢰니, 임금과 조정의 모든 신하가 듣고 크게 놀라 얼굴빛이 변하여 말하였다. \"어찌 근심이 되지 않겠는가. 즉시 의주로 공문을 보내되, 호국에서 길홍대라 하는 계집을 보내 이러이러한 일이 있었으니 만일 그런 사람이 내려가거든 부디 그 간계에 속지 말고 명심하라.\"","sp":[[19,22,"P","길홍대"],[201,203,"P","이시백"],[237,239,"P","이시백"],[264,266,"P","임금"],[341,344,"P","길홍대"]]},{"c":1,"sub":"","t":"하였다. 나라에서 박씨의 신명함에 탄복하고 충효를 칭찬하시며 공을 의논하여 정렬부인(貞烈夫人)의 품계를 내리시고 삼품의 녹을 먹게 하셨다. 임금께서 우의정에게 하교하셨다. \"경의 부인이 아니었으면 화를 어찌 면하였겠는가.\" 하시며 무도한 북쪽 오랑캐가 우리나라를 엿보니 어찌 통분하지 않겠는가 하셨다. 이후로는 적이 오는 기미를 자세히 알아 아뢰게 하셨다. 한편 길홍대가 본국에 들어가 뵈니 호왕이 물었다. \"이번에 조선에 나가 어찌하고 왔느냐?\" 길홍대가 아뢰었다.","sp":[[10,12,"P","박씨"],[42,46,"P","박씨"],[78,80,"P","임금"],[83,86,"P","이시백"],[100,102,"P","이득춘 부인"],[203,206,"P","길홍대"],[219,221,"P","호왕"],[251,254,"P","길홍대"]]},{"c":1,"sub":"","t":"\"소녀가 이번에 명을 받들고 큰일을 꾀하여 만 리 타국에 갔다가, 성공은커녕 만고에 짝이 없는 박씨라는 신인을 만나 목숨을 보전하지 못하고 타국의 원혼이 될 것을, 거듭 애걸하였을 뿐 아니라 어진 덕을 입어 살아왔습니다. 박씨가 하는 말이, 대왕께서 배은망덕하다 하며 짐승에 비유하여 꾸짖기를 그치지 않았습니다. 또 이르기를, 이런 분수 넘친 뜻을 두면 박씨가 비록 여자이나 영웅을 모아 본국에 들어와 멸망의 화를 주겠다 하였고, 너의 왕이 무도하여 이 같은 뜻을 둔다 하며 말이 바르고 곧았습니다. 그리고 이 말을 대왕께 전하라 하였습니다.\"","sp":[[53,55,"P","박씨"],[70,72,"P","임금"],[124,126,"P","박씨"],[198,200,"P","박씨"],[293,295,"P","임금"]]},{"c":1,"sub":"","t":"호왕이 크게 노하여 말하였다. \"네가 부질없이 나갔다가 공은 고사하고 큰일을 낭패하였으니 어찌 분하지 않겠느냐.\" 하며 급히 왕비를 청하여 말하였다. \"길홍대에게 조선에 나가 신인과 명장을 죽이고 오라 하였더니, 일을 이루기는커녕 큰일을 그르쳐 추한 소리를 듣게 하였으니 어찌 분하지 않으며, 또 조선을 도모하지 못하게 되었으니 이 분함을 어디 가서 갚겠소.\" 왕비가 대답하였다. \"제게 한 가지 계책이 있으니 행해 보십시다.\" 왕이 말하였다. \"무슨 계책이오? 듣고 싶소.\"","sp":[[0,2,"P","호왕"],[70,72,"P","호국 왕비"],[85,88,"P","길홍대"],[202,204,"P","호국 왕비"]]},{"c":1,"sub":"","t":"하니 왕비가 말하였다. \"조선에 비록 신인과 명장이 있으나 간신이 있어 충신의 말을 듣지 않을 것입니다. 이제 대왕께서 급히 대군을 거느려 조선을 치되, 북쪽으로는 가지 말고 곧장 동쪽으로 가서 동해를 건너 동대문을 치고 곧 장안을 짓밟으면 반드시 도성을 차지할 것입니다.\" 하니 호왕이 듣고 크게 기뻐하여 즉시 한우와 용골대(龍骨大)를 대장으로 삼아 정병 삼십만을 뽑아 주며 말하였다. \"경들을 가려 뽑아 보내니 부디 힘을 다하여 성공하되, 북으로 가지 말고 동으로 가서 동해를 건너 동대문을 깨뜨리고 들어가 장안을 몰래 덮치면 큰 공을 이룰 것이다. 삼가 조심하여 성공하고 돌아와 이름을 역사에 올려라.\"","sp":[[3,5,"P","호국 왕비"],[157,159,"P","호왕"],[175,177,"P","한우"],[179,182,"P","용골대"]]},{"c":1,"sub":"","t":"하니 두 장수가 명을 받고 나왔다. 왕비가 두 장수를 불러 분부하였다. \"그대들은 왕의 비밀 계책을 어기지 말고 지금 군사를 거느리고 가되, 조선 땅에 이르거든 날랜 군사를 시켜 의주와 도성을 오가는 길목에 매복하였다가 도성에서 의주부윤 임경업에게 소식을 통하지 못하게 하라. 장안을 칠 때 우의정 시백의 집 후원은 범하지 마라. 그 집 후원에 피화당이라는 초당이 있는데 사방에 신기한 나무가 무성할 것이니, 만일 범하면 성공은커녕 목숨을 보전하지 못하고 고국에 돌아오지 못할 것이다. 부디 명심하여 성공하고, 곧장 십만 대병을 거느리고 동으로 가서 동해를 건너 장안을 몰래 덮쳐라.\"","sp":[[20,22,"P","호국 왕비"],[128,132,"P","임경업"],[133,136,"P","임경업"],[163,166,"P","이시백"],[167,169,"P","이시백"],[247,249,"P","임금"]]},{"c":1,"sub":"","t":"하니 두 장수가 명을 받고 그날로 정병 십만을 거느리고 밤낮을 가리지 않고 조선을 향하였다. 한편 이때 박씨가 피화당에 있다가 승상을 청하여 말하였다. \"지금 북방 오랑캐가 군사를 일으켜 조선 땅에 이르렀으니, 급히 임금께 아뢰어 의주부윤 임경업을 불러 지금 동쪽으로 오는 적을 막게 하십시오.\" 승상이 크게 놀라 말하였다. \"내 소견으로는 적이 들어온다 하여도 북쪽 오랑캐이니 북쪽으로 와서 침범할 듯하오. 의주를 비우고 임경업을 불러올렸다가 오랑캐가 뜻밖에 들어와 북방을 빼앗으면 나라가 위태로울 것이니 그것이 근심이오. 부인은 무슨 까닭으로 북쪽은 염려하지 않고 동쪽을 걱정하여 막으라 하시오?\"","sp":[[58,60,"P","박씨"],[71,73,"P","이시백"],[121,123,"P","임금"],[129,133,"P","임경업"],[134,137,"P","임경업"],[166,168,"P","이시백"],[237,240,"P","임경업"],[294,296,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"\"북쪽 오랑캐는 본래 인의는 없고 간사한 꾀만 많아서, 임장군을 두려워하여 북쪽은 감히 범하지 못하고 동해를 건너 곧장 동대문을 깨뜨리고 들어와 도성을 어지럽힐 것이니 어찌 분하지 않겠습니까. 부디 제 말을 헛되이 여기지 마시고 급히 아뢰어 단단히 대비하십시오.\" 하거늘 승상이 듣고 옳게 여겨 급히 임금 앞에 들어가 부인이 하던 말을 낱낱이 아뢰었다. 임금께서 들으시고 크게 놀라 조정의 모든 신하를 모아 급히 의논하는데, 신하들이 당황하여 얼굴빛이 변한 채 어찌할 바를 몰랐다. 좌의정 원두표(元斗杓)가 반열에서 나와 아뢰었다. \"북쪽 오랑캐는 본래 간특합니다. 박씨의 말씀이 매우 옳으니 그 말을 따라 막는 것이 옳고, 급히 임경업을 불러올리는 것이 마땅합니다.\"","sp":[[31,34,"P","임경업"],[152,154,"P","이시백"],[168,170,"P","임금"],[178,180,"P","이득춘 부인"],[198,200,"P","임금"],[270,273,"P","원두표"],[274,277,"P","원두표"],[317,319,"P","박씨"],[353,356,"P","임경업"]]},{"c":1,"sub":"","t":"하니 말이 끝나기도 전에 한 재상이 얼굴빛을 바꾸며 아뢰었다. \"좌의정 원두표의 말은 지극히 옳지 않습니다. 북방 오랑캐는 여러 차례 임경업의 구원을 입었으니 무슨 힘을 믿고 우리 조선을 엿보겠습니까. 설사 군사를 일으켜 온다 해도 반드시 의주로 들어올 것입니다. 만일 의주를 비우고 임경업을 불러올려 동쪽을 지키다가 뜻밖에 적이 북쪽으로 들어와 진을 치고 이웃 고을을 빼앗으면, 북도의 강한 군사를 거두어 도성을 향해 올 것이니 그 형세가 매우 위태로울 것입니다. 누가 능히 당하겠습니까. 나라의 흥망이 아침저녁에 달려 있는데 어찌 요망한 계집의 말을 들으시고 중요한 땅에 있는 임경업을 불러올리려 하십니까. 적을 막으려면 의주를 굳게 지키는 것이 옳은데 동쪽으로 오는 적을 막으라 하니, 이는 나라를 망하게 하는 것이라 더욱 놀랍고 두렵습니다.\"","sp":[[36,39,"P","원두표"],[40,43,"P","원두표"],[75,78,"P","임경업"],[159,162,"P","임경업"],[325,328,"P","임경업"]]},{"c":1,"sub":"","t":"임금께서 말씀하셨다. \"박씨는 신명한 안목이 남달라 이미 시험한 일이 있거늘 어찌 요망하다 하는가. 그 말을 따라 동쪽으로 오는 적을 막는 것이 옳을까 한다.\" 그 재상이 또 아뢰었다. \"대저 해마다 풍년이 들고 나라가 태평하고 백성이 편안하여 태평한 거리에서 격양가를 일삼고 있는데, 이같이 태평한 시절에 조그마한 요괴로운 계집의 말을 퍼뜨려 조정을 놀라게 하고 민심을 어지럽게 하니 죄가 죽어도 아깝지 않고 지극히 요망합니다. 요망한 말을 들으시고 깊이 근심하시어 나라의 정사를 밝히지 않으시니, 원컨대 이 사람을 국법으로 다스리십시오.\"","sp":[[0,2,"P","임금"],[13,15,"P","박씨"]]},{"c":1,"sub":"","t":"하며 왕명을 무수히 거역하니, 이 사람은 대역무도한 김자점(金自點)이었다. 소인은 가까이하고 충신은 모함하여 나라의 권세를 제 마음대로 하였다. 이같이 헤아릴 수 없는 놈이 늘 나라 망하는 일만 좋아하여 나랏일을 다 폐하고 날마다 놀기만 일삼았으나, 신하들은 그 권세를 두려워하여 감히 입을 열지 못하였다. 임금께서도 크게 노하셨으나 머뭇거리며 결정하지 못하시니, 우의정 또한 막지 못하고 분한 마음을 이기지 못하여 곧장 집으로 돌아와 그 사연을 낱낱이 이야기하였다. 박씨가 듣고 하늘을 우러러 탄식하였다.","sp":[[29,32,"P","김자점"],[172,174,"P","임금"],[204,207,"P","이시백"],[262,264,"P","박씨"]]},{"c":1,"sub":"","t":"\"슬프다, 우리나라가 불행하여 간신의 조정이 되었구나. 지금 오랑캐가 머지않아 도성을 침범하게 되었는데 소인이 나라 권세를 잡아 위태롭게 되었으니 어찌 분하지 않겠습니까. 이제 내 말을 따라 바삐 임경업을 불러 정병을 뽑아 적이 오는 길에 매복하였다가 적이 이르거든 급히 막으면 수만 명의 군사라도 없앨 것이요, 사직을 보전하고 염려를 덜 것인데, 손을 묶고 적의 칼을 받으려 하니 어찌 망극하지 않겠습니까.\" 하며 승상에게 말하였다. \"나라에 뜻밖의 변이 있을 것이니 부디 용방(龍逢)과 비간(比干)의 충성을 다하여 사직을 받드십시오.\"","sp":[[110,113,"P","임경업"],[180,182,"P","임금"],[233,235,"P","이시백"]]},{"c":1,"sub":"","t":"하고 큰 소리로 통곡하니, 승상이 강개한 마음을 이기지 못하여 하늘을 우러러 탄식하고 대궐로 들어갔다. 이때는 병자년 섣달이었다. 홀연 동대문 쪽에서 대포 한 방 소리와 함께 북과 나팔 소리, 고함 소리가 천지를 진동하며 무수한 오랑캐 군사가 문을 깨뜨리고 물밀듯 들어왔다. 깃발과 칼과 창은 천지를 흔들고 살기가 성안에 가득하니 백성들은 뜻밖의 변을 당하였다. 오랑캐 장수가 군사를 호령하여 사방을 에워싸고 마구 짓치니 주검이 산처럼 쌓이고 울음소리가 성안에 가득하였다. 임금께서 황망하고 망극하여 어찌할 줄 몰라 말씀하셨다.","sp":[[15,17,"P","이시백"],[265,267,"P","임금"]]},{"c":1,"sub":"","t":"\"이제 적이 성안에 가득하여 백성을 죽이니 나라와 사직이 위태로움이 바로 눈앞에 있다. 어찌할꼬.\" 하시며 하늘을 우러러 탄식하시니 조정의 모든 신하와 궁중의 모든 사람이 다 목 놓아 통곡하였다. 이때 이승상이 임금을 모시고 있다가 여쭈었다. \"이제 사세가 급하니 남한산성으로 피란하십시다.\"","sp":[[114,116,"P","이시백"],[118,120,"P","임금"]]},{"c":1,"sub":"","t":"임금께서 정신이 어지러운 가운데 그 말을 옳게 여겨 옥교(玉轎)를 타시고 남문을 열고 남한산성으로 향하여 가시는데, 앞에서 적이 내달아 길을 막았다. 우의정이 마음과 힘을 다하여 적장을 물리치고 남한산성에 들어갔다. 이때 오랑캐 장수 한우와 용골대가 십만 대병을 거느리고 장안을 침범하는데, 곧장 군사를 몰아 대궐에 들어가니 대궐이 비어 있었다. 남한산성으로 피란한 줄 알고, 용골대의 아우 용울대(龍蔚大)에게 장안을 지키며 재물과 여자를 뒤지게 하고, 군사 백여 명을 거느리고 들어가 성을 에워싸고 쳐들어갔다.","sp":[[0,2,"P","임금"],[84,87,"P","이시백"],[131,133,"P","한우"],[135,138,"P","용골대"],[211,214,"P","용골대"],[219,222,"P","용울대"]]},{"c":1,"sub":"","t":"한편 이때 박씨는 일가친척 부인들을 피화당에 모아 난리를 피하고 있었다. 모든 부인이 용골대가 장안을 차지하여 재물과 여자를 뒤진다는 말을 듣고 놀라 도망하고자 하니 박씨가 말리며 말하였다. \"이제 사방을 적이 지키고 있는데 도망하면 어디로 가겠습니까. 도망하지 말고 있으면 자연히 화를 면할 도리가 있을 것입니다.\"","sp":[[6,8,"P","박씨"],[15,17,"P","이득춘 부인"],[44,46,"P","이득춘 부인"],[48,51,"P","용골대"],[93,95,"P","박씨"]]},{"c":1,"sub":"","t":"하였다. 이때 오랑캐 장수 용울대가 군사 백여 기를 거느리고 사방으로 다니며 재물과 여자를 찾다가 한 집에 이르러 바라보니, 정결한 초당이 있는데 앞뒤에 초목이 무성한 가운데 무수한 부인이 피란해 있었다. 용울대가 살펴보니 나무마다 용과 범이 머리와 꼬리를 잇대고 가지마다 뱀과 새가 되어 변화가 끝이 없고 살기가 가득하였다. 용울대는 박씨의 신기함을 알지 못하고 피화당에 있는 재물과 여자를 빼앗고자 급히 들어갔다. 그러자 순식간에 맑던 날에 검은 구름이 일어나며 천둥과 벼락이 천지를 진동하더니, 사방에 무성한 나무가 변하여 무수한 갑옷 입은 군사가 되어 점점 에워싸고, 가지와 잎사귀는 깃발과 칼과 창이 되어 위엄이 서리와 눈 같고 살기가 하늘을 찔렀다. 용울대가 그제야 우승상 집인 줄 알고 급히 도망하려 하였으나, 피화당 사방으로 칼 같은 바위가 하늘에 닿을 듯 겹겹이 둘러 길을 막았다. 용울대가 넋이 빠져 어찌할 줄 모르는데, 홀연 어떤 여자가 칼을 날리며 의젓이 나와 꾸짖었다.","sp":[[15,18,"P","용울대"],[102,104,"P","이득춘 부인"],[115,118,"P","용울대"],[183,186,"P","용울대"],[188,190,"P","박씨"],[370,373,"P","용울대"],[379,382,"P","이시백"],[447,450,"P","용울대"]]},{"c":1,"sub":"","t":"\"너는 어떤 도적이기에 당돌하게 들어와 남은 목숨을 재촉하느냐?\" 용울대가 합장하고 절하며 말하였다. \"누구 집인지 모르고 외람되이 들어왔거니와 은혜를 베풀어 남은 목숨을 살려 주십시오.\" 계화가 대답하였다. \"나는 이 집 시비 계화이거니와, 너는 무슨 까닭으로 죽을 곳에 들어왔느냐. 조그마한 힘만 믿고 이같이 하느냐. 우리 부인께서 네 머리를 베어 오라 하시기에 너를 베려고 왔으니 바삐 목을 늘여 내 칼을 받아라.\" 하니 용울대가 그 말을 듣고 크게 노하여 창을 들어 계화를 치려 하였으나, 창 든 손에 핏기가 가셨다. 울대가 하늘을 우러러 탄식하였다. \"슬프다. 대장부가 세상에 나서 한 나라의 대장이 되어 만 리 타국에 나왔다가 큰 공은커녕 조그마한 여자 손에 죽게 되니 어찌 통분하지 않겠는가.\"","sp":[[37,40,"P","용울대"],[106,108,"P","계화"],[125,130,"P","계화"],[183,185,"P","이득춘 부인"],[239,242,"P","용울대"],[265,267,"P","계화"],[294,296,"P","용울대"]]},{"c":1,"sub":"","t":"계화가 외쳤다. \"호국 장수 용울대야, 불쌍하고 가련하다. 대장부라는 이름으로 큰 공을 꾀하고 출전하였다가 큰 공은 어디 가고 남은 목숨이 허망하구나. 연약한 여자를 마주하여 탄식하며 눈물을 흘리니 웬일이냐. 너 같은 소장부야 말해 무엇하겠느냐. 내 말을 들어 보아라. 무도한 네 왕이 하늘의 뜻을 돌아보지 않고 외람되이 마음을 내어 우리 예의지국을 해치고자 너 같은 소장부를 보내 남은 목숨을 보전하지 못하게 되었으니, 네 왕의 일을 생각하면 우습고 가련하고, 또 네 목숨을 생각하면 측은하고 불쌍하다. 네 목숨이 오늘 내 손에 달렸으니 아무리 용서하고자 하나 하늘의 명을 거역하지 못하여 개 같은 목을 내 옥 같은 손으로 부득이 베니, 무지한 필부 놈아 나를 원망하지 마라.\"","sp":[[0,2,"P","계화"],[16,19,"P","용울대"],[54,56,"P","임금"],[222,224,"P","임금"]]},{"c":1,"sub":"","t":"하며 말을 마치자마자 칼을 날려 울대를 치니, 칼빛을 따라 머리가 떨어지고 몸이 뒤집혀 말에서 떨어졌다. 계화가 즉시 머리를 들고 피화당에 들어가 부인께 올리니, 부인이 울대의 머리를 문밖에 내던졌다. 그제야 바람과 구름이 고요해지고 날씨가 맑게 개었다. 다시 울대의 머리를 집어다가 후원 나무에 매달아 두고 여러 사람이 보게 하였다.","sp":[[18,20,"P","용울대"],[59,61,"P","계화"],[82,84,"P","이득춘 부인"],[91,93,"P","이득춘 부인"],[95,97,"P","용울대"],[146,148,"P","용울대"]]},{"c":1,"sub":"","t":"한편 슬프다. 국운이 불행하여 이 같은 변을 당하니, 전하께서는 남한산성으로 가시고 오랑캐는 물밀듯 쳐들어와 신하들을 사로잡으며 호령이 가을 서리 같았다. 한 번 호통에 무릎을 오랑캐에게 꿇어 항서를 써 올리니 어찌 분하지 않겠는가. 오랑캐가 곧장 들어가 왕비와 세자, 대군 삼 형제분을 사로잡아 호국으로 끌고 가려고 군사를 움직이니, 전하께서 이 모습을 보시고 통곡하며 기절하시고 조정의 모든 신하도 하늘을 우러러 통곡하였다. 시백이 전하를 위로하여 옥체를 보중하시라 하였다. 김자점이 나라 권세를 농락하여 나라를 망하게 하였으니 어찌 분하고 원통하지 않겠는가. 장안 백성이 남녀노소 없이 김자점의 살을 씹고자 하였다.","sp":[[30,32,"P","임금"],[143,145,"P","호국 왕비"],[147,149,"P","세자 삼 형제"],[151,159,"P","세자 삼 형제"],[188,190,"P","임금"],[240,242,"P","이시백"],[244,246,"P","임금"],[268,271,"P","김자점"],[331,334,"P","김자점"]]},{"c":1,"sub":"","t":"한편 이때 용골대가 장안으로 들어오는데 앞선 군사가 알리기를 용울대가 박부인의 시비 계화 손에 죽었다 하였다. 용골대가 듣고 기가 막혀 크게 소리 내어 통곡하니 이 또한 가관이었다. 용골대가 울음을 그치고 말하기를 '우리가 이미 조선에 나와 성공은 하였거니와 내 동생을 죽였으니 원수를 갚으리라.' 하고 바삐 말을 몰아 장안으로 향하였다. 어떤 집 후원 나무 끝에 울대의 머리가 매달려 있거늘, 머리를 보고 크게 통곡하며 앞선 군사에게 물었다. \"저 집이 우승상 이시백의 집이 아니냐?\"","sp":[[6,9,"P","용골대"],[34,37,"P","용울대"],[39,42,"P","박씨"],[44,49,"P","계화"],[62,65,"P","용골대"],[102,105,"P","용골대"],[204,206,"P","용울대"],[255,258,"P","이시백"],[259,262,"P","이시백"]]},{"c":1,"sub":"","t":"하니 앞선 군사가 대답하였다. \"그렇습니다.\" 용골대가 더욱 분을 이기지 못하여 곧장 칼을 들고 들어가려 하니, 적진 도원수 한우가 피화당 사방에 무성한 나무를 보고 크게 놀라 용골대를 말렸다. \"그대는 내 말을 듣고 가볍게 가지 마라. 초당 사방에 무성한 나무를 보니 범상치 않구나. 옛날 공명의 팔진도(八陣圖)와 사마양저(司馬穰苴)의 금사진(金鎖陣)을 겸하였으니 어찌 두렵지 않겠는가. 그대 동생은 본래 재주가 없어 저러한 험한 곳을 모르고 남을 가볍게 여겨 들어갔다가 목숨을 재촉하였으니 어찌 두렵지 않겠는가. 그대는 옛날 삼국 시절 육손(陸遜)의 일을 생각하여 저러한 험한 곳에 들지 마라.\"","sp":[[26,29,"P","용골대"],[63,69,"P","한우"],[70,72,"P","한우"],[99,102,"P","용골대"]]},{"c":1,"sub":"","t":"하니 용골대가 더욱 분을 참지 못하여 칼을 들고 땅을 두드리며 말하였다. \"그러면 우리 동생의 원수를 어찌 갚겠습니까. 만 리 타국에 형제가 함께 나왔다가 큰일을 이룬 뒤에 동생을 뜻밖에 죽이고 원수도 갚지 못하고 어찌 조그마한 여자에게 굴복한단 말입니까. 부끄러운 일은 남에게 들리게 해서는 안 되는 법이요, 또 더러운 소리는 면치 못할 것입니다.\" 하니 한우가 말하였다. \"그대가 한때의 분을 참지 못하여 용맹만 믿고 저러한 험한 곳에 들어갔다가는 원수 갚기는커녕 도리어 목숨을 보전하지 못할 것이니, 아직 잠깐 진정하여 그 신기한 재주를 살펴보라.","sp":[[3,6,"P","용골대"],[200,202,"P","한우"],[271,273,"P","임금"]]},{"c":1,"sub":"","t":"비록 억만 대병을 거느리고 들어갈지라도 그 안은 엿보지도 못하고 군사 하나도 살아오지 못할 것인데, 하물며 혼자 말을 타고 들어가고자 하니 지각이 그러하고서 어찌 살기를 바라겠는가. 이는 스스로 부르는 화이니 어찌 한 나라의 대장이 되겠는가.\" 용골대가 이 말을 옳게 여겨 들어가지는 못하고 군사에게 호령하여 저 나무를 에워싸고 한꺼번에 불을 놓으라 하였다. 그러자 홀연 미친 바람이 일어나며 오색구름이 자욱한 가운데 나무가 변하여 무수한 장졸이 되어 천지를 진동하고, 허다한 날아오르는 용과 사나운 범이 서로 이어 바람과 구름을 일으키니 천지가 아득하였다. 깃발과 창검은 앞뒤에 겹겹이 쌓이고 공중에서 신장(神將)이 내려와 신병(神兵)을 몰아 덮쳐 죽이니 함성 소리가 태산이 무너지는 듯하였다. 대오를 갖추지 못하여 오랑캐가 서로 밟혀 죽는 자가 헤아릴 수 없었다. 오랑캐 장수들이 황망한 가운데 남은 군사를 거두어 물러나니, 그제야 천지가 맑아지고 싸우는 소리가 그치며 신장이 간 데 없었다. 오랑캐 장수들이 보고 더욱 분을 이기지 못하여 다시 칼을 들고 달려들고자 하니, 맑던 날이 금세 또 어두워지며 구름과 안개가 크게 일어 지척을 분별할 수 없었다. 용골대가 감히 들지 못하고 울대의 머리만 바라보며 하늘을 우러러 탄식할 즈음, 나무 사이로 한 여자가 의젓이 나서며 크게 외쳤다.","sp":[[137,140,"P","용골대"],[593,596,"P","용골대"],[608,610,"P","용울대"]]},{"c":1,"sub":"","t":"\"이 무지한 용골대야, 네 동생이 내 칼에 죽었거늘 너조차 죽고자 하여 목숨을 재촉하느냐.\" 용골대가 이 말을 듣고 더욱 분하여 꾸짖었다. \"너는 어떤 여자이기에 대장부를 몰라보고 욕설로 희롱하느냐. 내 동생이 불행하여 네 손에 죽었거니와, 우리는 너의 나라 왕에게서 글월을 받았는데 네가 독하게 우리를 해치려 하느냐. 이는 과연 나라를 모르는 여자로다. 살아도 쓸 데 없으니 죽음을 재촉하거든 빨리 나와 내 칼을 받아라.\" 하니 계화가 그 말을 들은 체도 하지 않고 울대의 머리만 가리키며 무수히 조롱하였다. \"나는 박부인의 시비 계화이거니와 너를 생각하니 가련하고 하찮구나. 네 동생은 나같이 연약한 손에 죽었는데 너도 나를 당하지 못하니 어찌 불쌍하지 않으며 하찮지 않겠느냐.\"","sp":[[7,10,"P","용골대"],[52,55,"P","용골대"],[241,243,"P","계화"],[262,264,"P","용울대"],[290,293,"P","박씨"],[295,300,"P","계화"]]},{"c":1,"sub":"","t":"용골대가 듣고 분기가 크게 일어나 철궁에 왜전(倭箭)을 먹여 쏘니, 그 화살이 육십 보 안에 떨어지고 감히 맞히지 못하였다. 용골대가 더욱 분하여 군사에게 호령하여 한꺼번에 활을 쏘라 하니, 군사가 명을 받고 무수히 쏘았으나 화살이 하나도 맞지 않았다. 화살만 중간에서 허비하니 용골대가 기가 막혀 어찌할 줄 모르는 가운데, 그 신기함에 탄복하면서도 분한 마음을 참지 못하였다. 서로 이르기를 '우리 억만 대병이라도 감히 당하지 못할 것이니 이 나라 군사로 하여금 치게 하리라.' 하고 김자점을 불러 말하였다. \"너도 오늘부터는 우리나라 신하다. 바삐 군사를 뽑아 원수를 갚아라. 우리나라 신하가 되어 어찌 내 영을 거역하겠느냐. 만일 영을 어기면 군법으로 다스리리라.\"","sp":[[0,3,"P","용골대"],[70,73,"P","용골대"],[156,159,"P","용골대"],[272,275,"P","김자점"]]},{"c":1,"sub":"","t":"분부가 서리와 눈 같으니 김자점이 황공하여 대답하였다. \"어찌 장군의 영을 거역하겠습니까.\" 즉시 대포 한 방 소리와 함께 군사에게 호령하여 팔문금쇄진(八門金鎖陣)을 에워싸라 하니, 팔문금쇄진이 변하여 푸르고 푸른 소나무가 되었다. 오랑캐 장수가 그 변화를 보고 더욱 분하여 한 꾀를 생각하고, 군사에게 명하여 팔문금쇄진 사방을 깊이 파고 화약과 염초를 무수히 묻은 뒤 외쳤다. \"네가 아무리 천 명의 군사와 만 필의 말을 가졌다 한들 오늘이야 어찌 살기를 바라겠느냐. 죽기를 아끼거든 빨리 나와 항복하라.\"","sp":[[14,17,"P","김자점"]]},{"c":1,"sub":"","t":"하고 무수히 욕을 하였으나 피화당은 고요하여 아무 소리도 없었다. 오랑캐 장수가 군사에게 호령하여 한꺼번에 불을 지르니, 화약 터지는 소리가 천지가 무너지는 듯하고 불빛이 하늘을 찌르며 불길이 사방에서 일어났다. 박씨가 계화에게 명하여 옥병의 물을 초당 후원에 뿌리게 하고, 왼손에 옥화선(玉花扇)을 들고 오른손에 백화선(白花扇)을 들고 오색실로 부적을 매어 불길 속에 던지니, 한꺼번에 큰바람이 일어나며 화약 불이 도로 적군 진중으로 불어 갔다. 오랑캐 군사가 불길 속에 갇혀 천지를 분별하지 못하고 불에 타 죽는 자가 헤아릴 수 없었다. 용골대가 크게 놀라 급히 군사를 물리고 하늘을 우러러 탄식하였다.","sp":[[119,121,"P","박씨"],[123,125,"P","계화"],[303,306,"P","용골대"]]},{"c":1,"sub":"","t":"\"군사를 일으켜 나온 뒤 조선을 한 번 호통에 차지하고 승전고를 울리며 돌아가는 길에, 한낱 아녀자를 만나 불쌍한 동생을 죽이고 십만 대병을 거의 다 죽였으니 이 같은 분한 일은 어디 가서 갚으며, 또 무슨 면목으로 황상과 왕비께 뵙겠는가.\" 통곡을 그치지 않으며 여러 장수와 의논하였다. \"아무리 하여도 그 여자는 당하지 못할 것이니, 그 여자에게 원수 갚기는커녕 항복도 받을 수 없다. 급히 군사를 돌리는 것만 못하다.\"","sp":[[125,127,"P","호국 왕비"]]},{"c":1,"sub":"","t":"하고 즉시 장안의 재물과 사람, 왕대비와 세자 삼 형제분을 모시고 군사를 움직이니, 위아래 없이 울음소리가 장안을 진동하였다. 박씨가 분노를 이기지 못하여 계화를 시켜 크게 외치게 하였다. \"무지한 오랑캐야, 네 왕은 인의를 모르고 너같이 입에서 젖내 나는 것들을 보내 우리나라를 침범하니, 국운이 불행하여 패망을 당하였거니와 무슨 까닭으로 우리나라 사람들을 거두어 가느냐. 그러나 우리 왕대비는 모셔 가지 마라.\" 하니 오랑캐 장수가 그 말을 듣고 말하였다. \"네 말이 하찮고 가소롭구나. 우리가 이미 너의 나라에 와서 글월을 받았으니 데려가고 아니 데려가기는 우리 손안에 있다. 부질없는 말을 하지 마라.\"","sp":[[18,21,"P","왕대비"],[23,30,"P","세자 삼 형제"],[71,73,"P","박씨"],[87,89,"P","계화"],[217,220,"P","왕대비"]]},{"c":1,"sub":"","t":"하며 욕설을 무수히 하거늘 계화가 또 외쳤다. \"너희가 내 말을 끝내 거역하면 내 재주를 구경하여라.\" 말이 끝나기도 전에 무슨 진언을 두어 번 외니, 홀연 공중에 무지개 두 줄이 일어나며 급한 소나기가 폭포수처럼 쏟아져 천지가 아득하였다. 또 눈보라 치는 찬바람이 일어나며 우박이 퍼붓듯 하더니, 순식간에 소나기와 우박이 얼음이 되어 오랑캐의 말굽이 땅에 붙어 떨어지지 않아 한 걸음도 움직이지 못하였다. 오랑캐 장수가 그제야 깨닫고 말하였다.","sp":[[15,17,"P","계화"]]},{"c":1,"sub":"","t":"\"처음 군사를 일으킬 때 왕비께서 분부하시기를 조선에 가거든 장안에 신인이 있을 것이니 부디 우승상 집 후원을 범하지 말라 하셨는데, 우리가 깨닫지 못하고 한때의 분을 참지 못하여 왕비의 분부를 거역하다가 도리어 재앙을 받아 십만 대병을 거의 다 죽였을 뿐 아니라 울대를 죽였으니 무슨 면목으로 왕과 왕비를 뵙겠는가. 이제 사세가 급하니 곧장 박씨께 비는 것만 못하다.\" 하고 오랑캐 장수들이 한꺼번에 갑옷과 투구를 벗어 말안장 위에 걸고 말에서 내려 손목을 묶고 팔문금쇄진 앞에 나아가 엎드려 애걸하였다. \"소장들이 군사를 일으켜 조선에 나왔으나 무릎을 한 번도 꿇은 적이 없었는데, 이제 박부인의 신명하심에 빕니다. 부인의 말씀을 따라 왕대비는 모셔 가지 않겠습니다.\"","sp":[[14,16,"P","호국 왕비"],[52,55,"P","이시백"],[101,103,"P","호국 왕비"],[148,150,"P","용울대"],[168,170,"P","호국 왕비"],[192,194,"P","박씨"],[331,334,"P","박씨"],[347,349,"P","이득춘 부인"],[358,361,"P","왕대비"]]},{"c":1,"sub":"","t":"하며 무수히 애걸하니, 그제야 부인이 주렴을 걷고 나서며 꾸짖었다. \"너희를 씨도 없이 죽이자 하였으나 너그럽게 용서하여 하늘의 명을 따르게 하거니와, 우리나라가 불행하여 너희에게 글월을 주었으나 죄 없는 우리 왕대비와 세자를 굳이 모셔 가려 하니 어찌 용서가 있겠느냐. 그러나 모두가 운수이니 하늘의 명을 따르게 하는 것이다. 너희 말대로 왕대비는 모셔 가지 말고, 부득이 세자 삼 형제분을 모셔 간다 하니 그 또한 하늘의 뜻을 거역하지 못하겠거니와 부디 조심하여 모셔 가라. 나는 이곳에 있어도 아는 도리가 있으니, 만일 편치 않게 모셔 가면 곧 신장을 보내 너희를 씨도 없이 없앤 뒤에 내 몸소 네 나라에 들어가 네 왕을 사로잡고 죄 없는 백성까지 없애 분을 풀 것이다. 부디 내 말을 헛되이 여기지 마라.\"","sp":[[17,19,"P","이득춘 부인"],[118,121,"P","왕대비"],[123,125,"P","세자 삼 형제"],[191,194,"P","왕대비"],[210,217,"P","세자 삼 형제"]]},{"c":1,"sub":"","t":"하시니 오랑캐 장수들이 무수히 사례하였다. 용골대가 다시 애걸하였다. \"소장의 동생 머리를 주시면 부인의 덕택을 죽어 백골이 되어도 잊지 못하겠습니다. 깊이 헤아려 주시면 고국에 돌아가겠으니 처분해 주십시오.\" 부인이 말하였다. \"옛날 조양자(趙襄子)는 지백(智伯)의 머리에 옻칠을 하여 술잔을 만들어 두고 원수를 갚았다. 나도 옛사람의 일을 본받아 네 동생의 머리에 옻칠을 하여 술잔을 만들어, 남한산성에 피란하신 분함을 만분의 일이라도 풀까 한다. 네 처지는 딱하나 저마다 제 나라를 섬기는 것은 마찬가지다. 아무리 애걸하여도 그것은 못하겠다.\"","sp":[[24,27,"P","용골대"],[55,57,"P","이득춘 부인"],[118,120,"P","이득춘 부인"]]},{"c":1,"sub":"","t":"하니 용골대는 크게 통곡할 따름이요, 하릴없이 부인께 하직하였다. 부인이 또 일렀다. \"너희는 그 길로 가지 말고 의주로 가다가 임장군을 찾아보아라.\" 하니 오랑캐 장수들은 그 계교를 알지 못하고 속으로 생각하기를 '우리가 조선 왕의 글월을 받았으니 서로 떠나는 것이 무슨 상관이겠는가.' 하였다. 다시 하직한 뒤 왕대비는 도로 환궁하시고, 세자 삼 형제분을 모시고 본국으로 돌아가는데 의주로 향하였다. 이때 잡혀가는 사람들이 하늘을 우러러 통곡하며 서로 보고 말하였다. \"어찌 박부인은 화를 면하고 고국에 편히 계시고 우리는 무슨 죄로 만 리 타국에 잡혀가는가. 이제 가면 언제나 고국산천을 다시 볼까.\"","sp":[[3,6,"P","용골대"],[26,28,"P","이득춘 부인"],[37,39,"P","이득춘 부인"],[72,75,"P","임경업"],[176,179,"P","왕대비"],[191,198,"P","세자 삼 형제"],[268,271,"P","박씨"]]},{"c":1,"sub":"","t":"하며 눈물을 금치 못하니, 박부인이 계화를 시켜 외치게 하였다. \"인간의 괴로움과 즐거움은 사람에게 늘 있는 일이니 너무 서러워 말고 안심하고 가십시오. 십 년 뒤에 호국에 들어가 세자 삼 형제분을 모셔 올 사람이 있을 것이니 부디 먼 길에 평안히 가십시오.\" 하며 온갖 말로 위로하였다. 오랑캐 장수들이 조선에 나올 때 왕비의 말을 들어 북으로 가지 않고 동해를 건너왔으며, 날랜 군사 삼천을 보내 의주에서 서울 가는 길 중간에 매복시켜 서로 소식을 통하지 못하게 하였었다.","sp":[[15,18,"P","박씨"],[20,22,"P","계화"],[101,108,"P","세자 삼 형제"],[180,182,"P","호국 왕비"]]},{"c":1,"sub":"","t":"한편 이때 사자가 뜻밖의 변을 의주로 알리려 하였으나 중간에서 막혔으므로 임경업이 이 기별을 늦게야 듣고 밤낮으로 올라오는데, 앞에서 복병이 나와 길을 막았다. 경업이 칼을 들고 한 번에 물리치고 오는데, 이때 오랑캐 장수들이 의기양양하여 의주를 향해 오고 있었다. 경업이 바라보고 분을 이기지 못하여 달려들어 우선 선봉장을 베고, 왼쪽으로 찌르고 오른쪽으로 부딪치며 사람 없는 곳처럼 휘저어 장졸을 무수히 짓찧으니, 오랑캐 장수들이 감히 당하지 못하여 죽은 자가 헤아릴 수 없었다. 용골대와 한우가 하늘을 우러러 탄식하며 부인을 원망하고, 즉시 글월을 갖추어 경업에게 보냈다. 이때 임장군이 오랑캐 군사를 거의 다 짓찧게 되었는데, 사자가 임금의 전교를 올리니 경업이 북쪽을 향해 절하고 받아 보았다. 그 글에 이르기를,","sp":[[41,44,"P","임경업"],[90,92,"P","임경업"],[149,151,"P","임경업"],[271,274,"P","용골대"],[276,278,"P","한우"],[293,295,"P","이득춘 부인"],[314,316,"P","임경업"],[327,330,"P","임경업"],[359,361,"P","임금"],[371,373,"P","임경업"]]},{"c":1,"sub":"","t":"\"오호라, 국운이 불행하여 아무 달 아무 날에 오랑캐가 달려들어 성안을 짓밟으니 하릴없이 남한산성으로 피란하였는데, 십만 대병이 그곳으로 달려들어 한 번 호통에 하릴없이 글월을 써 주었으니 어찌 슬프지 않겠는가. 이 모두 하늘의 운수다. 경의 충성이 이제는 쓸 데가 없이 되어 공은 있어도 보람이 없게 되었으니[?] 어찌 분하지 않으며 한심하지 않겠는가. 이미 지난 일이니 오랑캐에게 길이나 빌려주어 돌아가게 하라.\" 하였다. 경업이 다 보고 나서 분을 참지 못하여 칼을 던지고 크게 통곡하였다. \"우리나라의 만고 소인이 나라 권세를 마음대로 하여 이같이 되었으니 밝은 하늘이 어찌 무심한가.\" 하며 울기를 그치지 않다가, 끝내 분한 마음을 이기지 못하여 다시 칼을 들고 내달아 오랑캐 장수를 잡아 엎어 놓고 큰 소리로 꾸짖었다.","sp":[[239,241,"P","임경업"]]},{"c":1,"sub":"","t":"\"네 나라가 지금까지 버틴 것도 우리 힘인 줄 모르고 무도한 오랑캐 놈들이 우리나라를 침범하니, 분한 마음으로는 너희 놈들을 씨도 없이 죽일 것이로되, 너희 목에 다시 칼을 대기가 더러울 뿐 아니라 이미 국운이 불행하다. 왕명을 거역하지 못하여 곧 용서하고 너희를 살려 보낸다.\" 하고 군곤(軍棍) 서른 대를 쳐서 놓아 보내며 다시 분부하기를, 세자 삼 형제분을 평안히 모셔 가고 착실히 공경하여 대접하라 하였다. 한바탕 통곡한 뒤에 길을 빌려 보내었다. 한편 임금께서 처음에 박부인의 말을 듣지 않은 것을 뉘우치고 스스로 꾸짖으셨고, 또 신하들이 탄식하였다. \"슬프다. 박부인 말대로 하였으면 어찌 이같이 망극한 변을 당하였겠는가.\"","sp":[[193,200,"P","세자 삼 형제"],[258,260,"P","임금"],[267,270,"P","박씨"],[320,323,"P","박씨"]]},{"c":1,"sub":"","t":"하며 임금께서 또 탄식하셨다. \"박부인이 만일 남자로 태어났더라면 오랑캐를 어찌 두려워하였겠는가. 그러나 여인이 맨손에 칼 한 자루로 싸움에 이겨 조선을 빛나게 하였으니 이는 고금에 없는 일이다.\" 하시고 이조에 명을 내려 박부인에게 충렬(忠烈)의 직첩을 내리시고, 또 궁녀를 보내 위로하셨다. \"오호라, 과인이 밝지 못하여 부인의 신명한 안목과 나라를 위한 충성을 쓰지 않다가 이같이 망극한 변을 당하였으니, 이 또한 하늘의 운수라 누구를 원망하고 누구를 탓하겠는가. 그러나 밝은 하늘이 감동할 것이다. 정절과 충심을 다하여 나랏일을 살피시고, 자손을 두어 오래 복을 누리며 만세에 이름을 길이 전하게 하라.\"","sp":[[3,5,"P","임금"],[18,21,"P","박씨"],[125,128,"P","박씨"],[182,184,"P","이득춘 부인"],[334,336,"P","임금"]]},{"c":1,"sub":"","t":"하였다. 박씨가 궁녀를 대하여 나라의 은혜에 감사하고 말하였다. \"제가 하늘이 내린 다행으로 왕대비를 모셔 가지 못하게 한 것은 임금의 은혜를 생각해서였고, 세자를 모셔 가게 한 것은 하늘의 뜻을 따르게 하려는 것이었습니다. 오랑캐 장수를 의주로 가게 한 것은 임장군을 만나게 하려는 것이었고, 임장군을 만나게 한 것은 영웅이 분을 풀게 하려는 것이었습니다.\"","sp":[[5,7,"P","박씨"],[25,27,"P","이시백"],[52,55,"P","왕대비"],[72,74,"P","임금"],[88,90,"P","세자 삼 형제"],[146,149,"P","임경업"],[165,168,"P","임경업"]]},{"c":1,"sub":"","t":"박부인이 이 뒤로부터 나라 섬기기를 인의와 충성으로 하니, 이런 부인은 아무리 여자라도 그 신기한 재주와 지극한 충절을 누가 칭송하지 않으며 이름이 어찌 후세에 전하지 않겠는가. 참으로 부러워할 만하고 탄복할 만하니 박씨의 이름은 만세토록 잊히지 않으리라 하였다. 어화, 세상 사람들아, 내 말씀 들어 보시오. 남자라도 못할 일을 여자가 행하였으니 어찌 아름답지 않으며 어찌 신기하지 않겠소. 노인이든 남녀노소 누구든 한번 보시거든 부디 마음 깊이 새기시오. 이 책이 하루 저녁 소일할 만하기에 변변찮은 글씨로 베껴 썼으니 그대로 너그러이 보아 주시오.","sp":[[0,3,"P","박씨"],[36,38,"P","이득춘 부인"],[90,92,"P","임금"],[121,123,"P","박씨"]]}]});
